def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    # Remove a leading 'v' or 'V' if present
    if s.startswith(('v', 'V')):
        s = s[1:]
    parts = s.split('.')
    nums = []
    for part in parts:
        # Extract the leading numeric component of each part
        num_str = ''
        for ch in part:
            if ch.isdigit():
                num_str += ch
            else:
                break
        if num_str:
            nums.append(int(num_str))
    return tuple(nums)

