def extostr(cls, e, max_level=30, max_path_level=5):
    """Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    try:
        tb = e.__traceback__
    except AttributeError:
        tb = None
    if not tb:
        tb = sys.exc_info()[2]
    stack = traceback.extract_tb(tb) if tb else []
    if len(stack) > max_level:
        stack = stack[:max_level]
    lines = []
    for i, (filename, lineno, func, line) in enumerate(stack):
        parts = os.path.normpath(filename).split(os.sep)
        if len(parts) > max_path_level:
            filename = os.path.join('...', *parts[-max_path_level:])
        lines.append(f'{i + 1}  {func} ({filename}:{lineno})')
    msg = f'[{e.__class__.__name__}] {e}'
    if lines:
        return msg + '\nTraceback (most recent call last):\n' + '\n'.join(lines)
    return msg

