def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    kept = []
    for i, cls in enumerate(classes):
        # If the item is not a class there is nothing to reduce
        if not isinstance(cls, type):
            kept.append(cls)
            continue
        # Skip if an already kept class is a subclass of this one
        if any(isinstance(k, type) and issubclass(k, cls) for k in kept):
            continue
        # Skip if a later class in the list is a subclass of this one
        if any(isinstance(l, type) and issubclass(l, cls) for l in classes[i + 1:]):
            continue
        kept.append(cls)
    return kept

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    result = []
    for cls in classes:
        # Skip if this class is a subclass of another in the list
        if not any(issubclass(other, cls) for other in classes if other is not cls):
            result.append(cls)
    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    return [cls for cls in classes if not any(
        other is not cls and issubclass(other, cls) for other in classes
    )]

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal = []
    for cls in classes:
        if cls in minimal:
            continue
        # skip if this base is a subclass of any already selected base
        if any(issubclass(cls, base) for base in minimal):
            continue
        minimal.append(cls)
    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Preserve original order and remove any class that is a subclass
    # of another class in the input list.
    minimal = []
    for cls in classes:
        # Skip if `cls` is a subclass of another class in the list.
        is_redundant = False
        for other in classes:
            if other is cls:
                continue
            try:
                if issubclass(cls, other):
                    is_redundant = True
                    break
            except TypeError:
                # Skip objects that aren't types.
                pass
        if not is_redundant:
            minimal.append(cls)
    return list(minimal)

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    result = []
    if all:
        # Include all public attributes from this class and base classes
        for name in dir(self.__class__):
            if name.startswith('_'):
                continue
            obj = getattr(self.__class__, name)
            description = getattr(obj, "__doc__", None) or ""
            result.append((name, description))
    else:
        # Only the attributes defined directly on this class
        for name, obj in self.__class__.__dict__.items():
            if name.startswith('_'):
                continue
            description = getattr(obj, "__doc__", None) or ""
            result.append((name, description))
    result.sort(key=lambda x: x[0])
    return result

def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    iface = self.__class__
    result = {}
    for cls in reversed(iface.__mro__):
        for name, attr in cls.__dict__.items():
            if name.startswith('_'):
                continue
            if callable(attr):
                continue
            desc = None
            if hasattr(attr, "__doc__") and attr.__doc__:
                desc = attr.__doc__
            if desc is None and hasattr(attr, "description") and attr.description:
                desc = attr.description
            if desc:
                result[name] = desc.strip()
    if all:
        return result
    return list(result.keys())

