    """
    self.context = {}
    if hasattr(self, "initial_value") and self.initial_value is not None:
        self.counts = self.initial_value
    else:
        self.counts = self.make_bins()

def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset the current context
        self.context = {}
        # Reinitialize the bins
        if hasattr(self, 'initial_value') and hasattr(self, 'bins'):
            # Fill existing bins with the initial value
            try:
                n = len(self.bins)
                self.bins = [self.initial_value] * n
            except Exception:
                # Fallback if bins is not a sequence
                self.bins = self.make_bins()
        else:
            # If no explicit initial value, use make_bins()
            self.bins = self.make_bins()

