    if hasattr(self, "initial_value") and self.initial_value is not None:
        # If bins exist, reset each to the initial value
        if hasattr(self, "bins") and isinstance(self.bins, (list, tuple)):
            self.bins = [self.initial_value for _ in self.bins]
        else:
            self.bins = [self.initial_value]
    else:
        # Fallback: create new bins with make_bins if available
        if hasattr(self, "make_bins") and callable(self.make_bins):
            self.bins = self.make_bins()
        else:
            self.bins = []

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the current context
    self.context = {}

    bins = getattr(self, 'bins', None)

    if bins is not None:
        # Reinitialize existing bins with the initial value if provided
        if hasattr(self, 'initial_value'):
            try:
                # Handle list/tuple bins
                for i in range(len(bins)):
                    bins[i] = self.initial_value  # type: ignore
            except TypeError:
                # Handle dict bins
                for key in bins:
                    bins[key] = self.initial_value  # type: ignore
        else:
            # No explicit initial_value, keep current bins as they are
            pass
    else:
        # No bins yet; create them via make_bins()
        self.bins = self.make_bins()

def to_csv(self, separator=",", header=None):
    """Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    # Determine the iterable of points: prefer attribute `points`,
    # otherwise assume the instance itself is iterable.
    points_iter = getattr(self, "points", None)
    if points_iter is None:
        points_iter = self

    lines = []
    if header is not None:
        lines.append(header)

    for point in points_iter:
        # Expecting point to be a tuple (coordinate, value)
        try:
            coordinate, value = point
        except Exception:
            # If point cannot be unpacked, skip it
            continue

        # Convert coordinate parts to string
        if isinstance(coordinate, (str, bytes)):
            coord_parts = [str(coordinate)]
        elif hasattr(coordinate, "__iter__"):
            coord_parts = [str(p) for p in coordinate]
        else:
            coord_parts = [str(coordinate)]

        # Convert value parts to string
        if isinstance(value, (str, bytes)):
            val_parts = [str(value)]
        elif hasattr(value, "__iter__"):
            val_parts = [str(v) for v in value]
        else:
            val_parts = [str(value)]

        row = separator.join(coord_parts + val_parts)
        lines.append(row)

    return "\n".join(lines)

