    lines = []
    if header is not None:
        lines.append(str(header))
    for point in self:
        try:
            coord, value = point
        except Exception:
            coord = point
            value = None
        if isinstance(coord, (list, tuple)):
            coord_str = separator.join(map(str, coord))
        else:
            coord_str = str(coord)
        if value is None:
            line = coord_str
        else:
            if isinstance(value, (list, tuple)):
                value_str = separator.join(map(str, value))
            else:
                value_str = str(value)
            line = coord_str + separator + value_str
        lines.append(line)
    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    err_indices = []

    # Prefer a pre‑computed mapping if it exists
    if hasattr(self, 'err_index_map') and coord_name in self.err_index_map:
        return list(self.err_index_map[coord_name])

    # Fall back to heuristic based on variable name patterns
    # e.g. 'x_err', 'y_error', 'err_x', etc.
    for idx, var in enumerate(self._variables):
        # Attempt to obtain a useful name string for the variable
        var_name = getattr(var, 'name', None)
        if var_name is None:
            var_name = getattr(var, 'variable', None)
        if not isinstance(var_name, str):
            continue

        # Common patterns: <coord>_err, <coord>_error, err_<coord>, error_<coord>
        patterns = [
            f"{coord_name}_err",
            f"{coord_name}_error",
            f"err_{coord_name}",
            f"error_{coord_name}"
        ]
        if var_name in patterns:
            err_indices.append(idx)

    return err_indices

def _get_err_indices(self, coord_name):
        """Get error indices corresponding to a coordinate."""
        # Retrieve the error array for the requested coordinate.  Different
        # implementations may store the errors under different attribute
        # names, so we fall back on a few common possibilities.
        err_arr = None
        if hasattr(self, "_errors") and isinstance(self._errors, dict):
            err_arr = self._errors.get(coord_name)
        if err_arr is None and hasattr(self, "_err_coords") and isinstance(self._err_coords, dict):
            err_arr = self._err_coords.get(coord_name)

        # If we still have nothing to work with, return an empty index array.
        if err_arr is None:
            return np.array([], dtype=int)

        # Ensure we are working with a NumPy array.
        if not isinstance(err_arr, np.ndarray):
            err_arr = np.array(err_arr)

        # Return the indices where the error is non‑zero and not NaN.
        return np.nonzero(np.logical_and(np.isfinite(err_arr), err_arr != 0))[0]

def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    # Ensure the context has the necessary dictionaries
    if not hasattr(context, 'error'):
        context.error = {}
    if not hasattr(context, 'value'):
        context.value = {}

    # Map coordinate names for the first three fields
    coord_names = ['x', 'y', 'z']
    base_fields = [f for f in self._fields if not f.startswith('error_')]
    col_coord_map = {}
    for i, name in enumerate(base_fields):
        if i < len(coord_names):
            col_coord_map[name] = coord_names[i]

    # Process all error columns
    for err_col in [f for f in self._fields if f.startswith('error_')]:
        remainder = err_col[len('error_'):]
        parts = remainder.split('_', 1)
        base = parts[0]
        suffix = parts[1] if len(parts) > 1 else ''
        coord = col_coord_map.get(base)
        if not coord:
            continue
        key = f"{coord}_{suffix}" if suffix else coord

        # Collect indices where the error value is present
        vals = self._values.get(err_col, [])
        indices = []
        for idx, v in enumerate(vals):
            try:
                if v is not None and not np.isnan(v):
                    indices.append(idx)
            except Exception:
                if v is not None:
                    indices.append(idx)

        if indices:
            context.error[key] = {'index': indices}

    # Add non‑error fields to context.value if not already present
    for fname in base_fields:
        if fname not in context.value:
            context.value[fname] = self._values.get(fname)

    return context

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Strings and bytes are not sequences we care about
    if isinstance(seq, (str, bytes)):
        return False
    # Exclude explicit Source sequences
    try:
        if isinstance(seq, Source):
            return False
    except NameError:
        # Source not defined; ignore
        pass
    # Check if seq itself is a FillRequest element
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        # FillRequest not defined; fall through
        pass
    # If seq is iterable, check elements
    try:
        for elem in seq:
            try:
                if isinstance(elem, FillRequest):
                    return True
            except NameError:
                # If FillRequest unknown, skip element
                pass
    except TypeError:
        # seq not iterable
        pass
    return False

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element or contains at least one such,
    and it is not a Source sequence.
    """
    # If *seq* itself is a FillRequest instance, we can directly use it
    if isinstance(seq, FillRequest):
        # Ensure it is not also a Source type
        return not isinstance(seq, Source)

    # If *seq* is a Source sequence, we cannot treat it as a FillRequestSeq
    if isinstance(seq, Source):
        return False

    # Attempt to iterate over *seq* to examine its elements
    try:
        iterator = iter(seq)
    except TypeError:
        # Not iterable, so cannot be a FillRequestSeq
        return False

    # Avoid treating strings or bytes as sequences
    if isinstance(seq, (str, bytes)):
        return False

    for element in iterator:
        if isinstance(element, FillRequest):
            return not isinstance(element, Source)

    return False

