def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1, if a key is present both in *d1* and *d2*
    but has different values, it is included into the difference.
    """
    diff = {}
    for k, v1 in d1.items():
        if k not in d2:
            diff[k] = v1
        else:
            v2 = d2[k]
            if isinstance(v1, dict) and isinstance(v2, dict) and (level == -1 or level > 1):
                new_level = -1 if level == -1 else level - 1
                subdiff = difference(v1, v2, new_level)
                if subdiff:
                    diff[k] = subdiff
            else:
                if level == -1 or level > 0:
                    if v1 != v2:
                        diff[k] = v1
    return diff

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both arguments must be dictionaries")
    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            # key only in d1 – include it. For dict values we return the
            # subdictionary directly; this is safe because the caller
            # should not modify the result in place if that matters.
            result[key] = val1
        else:
            val2 = d2[key]
            if isinstance(val1, dict) and isinstance(val2, dict):
                if level == 0:
                    # No deeper recursion; treat as atomic value
                    if val1 != val2:
                        result[key] = val1
                else:
                    # Perform recursive difference
                    next_level = -1 if level == -1 else level - 1
                    subdiff = difference(val1, val2, next_level)
                    if subdiff:
                        result[key] = subdiff
            else:
                # Non-dict values: include if they differ
                if val1 != val2:
                    result[key] = val1
    return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    def _diff(a, b, lev):
        res = {}
        for k, val in a.items():
            if k not in b:
                # include a copy of the value
                if isinstance(val, dict):
                    # recursive copy to avoid mutating the original
                    sub = _diff(val, {}, lev-1 if lev > 0 else lev)
                    res[k] = sub
                else:
                    res[k] = val
            else:
                bval = b[k]
                if isinstance(val, dict) and isinstance(bval, dict) and (lev > 0 or lev == -1):
                    sub = _diff(val, bval, lev-1 if lev > 0 else lev)
                    if sub:
                        res[k] = sub
                else:
                    if val != bval:
                        res[k] = val
        return res

    return _diff(d1, d2, level)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    errors = []
    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            try:
                if not re.match(LABEL_KEY_REGEX, key):
                    errors.append({key: f"Label key '{key}' does not match the regex [...]"})
            except TypeError:
                errors.append({key: 'expected string or bytes-like object'})

        # Validate value(s)
        if isinstance(value, (list, tuple)):
            for element in value:
                if not isinstance(element, (str, bytes)):
                    errors.append({str(element): 'expected string or bytes-like object'})
                else:
                    try:
                        if not re.match(LABEL_VALUE_REGEX, element):
                            errors.append({element: f"Label value '{element}' does not match the regex [...]"})
                    except TypeError:
                        errors.append({element: 'expected string or bytes-like object'})
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                try:
                    if not re.match(LABEL_VALUE_REGEX, value):
                        errors.append({value: f"Label value '{value}' does not match the regex [...]"})
                except TypeError:
                    errors.append({value: 'expected string or bytes-like object'})

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    messages = []

    # Assume the regex patterns are defined elsewhere in the module.
    # LABEL_KEY_REGEX and LABEL_VALUE_REGEX should be precompiled regex objects.
    key_pattern = getattr(_validate_labels, "LABEL_KEY_REGEX", None)
    value_pattern = getattr(_validate_labels, "LABEL_VALUE_REGEX", None)

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            messages.append({str(key): "expected string or bytes-like object"})
        else:
            # Validate key regex
            if key_pattern and not key_pattern.match(key):
                messages.append({key: f"Label key '{key}' does not match the regex [...]"})

        # Helper function to validate a single value (including elements of lists)
        def _validate_single(val):
            # Value must be string or bytes
            if not isinstance(val, (str, bytes)):
                messages.append({str(val): "expected string or bytes-like object"})
            else:
                # Value must match its regex
                if value_pattern and not value_pattern.match(val):
                    messages.append({val: f"Label value '{val}' does not match the regex [...]"})

        # Validate value
        if isinstance(value, list):
            for v in value:
                _validate_single(v)
        else:
            _validate_single(value)

    if messages:
        raise ValidationError(messages)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
