        # Validate key type
        if not isinstance(key, (str, bytes)):
            messages.append({str(key): 'expected string or bytes-like object'})
        else:
            # Validate key against regex
            try:
                if not KEY_REGEX.search(key):
                    messages.append(
                        {str(key): "Label key '%s' does not match the regex [...]" % key}
                    )
            except Exception:
                # If regex itself fails, propagate
                raise

        # Validate value type
        if not isinstance(value, (str, bytes)):
            messages.append({str(value): 'expected string or bytes-like object'})
        else:
            # Validate value against regex
            if not VALUE_REGEX.search(value):
                messages.append(
                    {str(value): "Label value '%s' does not match the regex [...]" % value}
                )

    if messages:
        raise ValidationError(messages)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions."""

    errors = []

    # Regular expressions for keys and values.
    key_regex = re.compile(r'^[a-zA-Z][a-zA-Z0-9_-]*$')
    value_regex = re.compile(r'^.*$')

    for key, val in labels.items():
        # Validate key type.
        key_key = str(key)
        if not isinstance(key, (str, bytes)):
            errors.append({key_key: 'expected string or bytes-like object'})
        else:
            if not key_regex.match(key):
                errors.append({key: f"Label key '{key}' does not match the regex [{key_regex.pattern}]"})
        # Validate value type.
        val_key = str(val)
        if not isinstance(val, (str, bytes)):
            errors.append({val_key: 'expected string or bytes-like object'})
        else:
            if not value_regex.match(val):
                errors.append({val: f"Label value '{val}' does not match the regex [{value_regex.pattern}]"})

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        return {}

    def _convert(item, top_level):
        if isinstance(item, dict):
            return {
                k: _convert(v, top_level)
                for k, v in item.items()
            }
        if isinstance(item, list):
            return [
                _convert(elem, top_level)
                for elem in item
            ]
        # non-dict and non-list: keep value only if we are at first level (top-level)
        return item if top_level else None

    # copy top-level fields for first_level case, otherwise set to None
    result = {}
    for key, val in manifest_dict.items():
        if isinstance(val, dict):
            result[key] = _convert(val, first_level)
        elif isinstance(val, list):
            result[key] = _convert(val, first_level)
        else:
            result[key] = val if first_level else None

    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Special handling for top‑level metadata when first_level is True
            if first_level and key == "metadata":
                meta_copy = {}
                for meta_key, meta_val in value.items():
                    # Preserve common identifiers; everything else becomes None
                    if meta_key in ("name", "namespace", "uid"):
                        meta_copy[meta_key] = meta_val
                    else:
                        meta_copy[meta_key] = None
                result[key] = meta_copy
            else:
                result[key] = generate_default_observer_schema_dict(value, first_level=first_level)
        elif isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    new_list.append(None)
            result[key] = new_list
        else:
            # For top‑level identifying fields we keep the value when first_level is True
            if first_level and key in ("apiVersion", "kind"):
                result[key] = value
            else:
                result[key] = None
    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """

    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recurse into nested dictionaries, always treat them as non‑first level.
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Preserve the list structure, but apply the same rules to the first item.
            if not value:
                result[key] = []
            else:
                first = value[0]
                if isinstance(first, dict):
                    result[key] = [generate_default_observer_schema_dict(first, first_level=False)]
                else:
                    result[key] = [None]
        else:
            # Scalar value: keep the value only if we are at the top level and this key
            # is an identifying field. Otherwise replace with None.
            if first_level and key in ("apiVersion", "kind"):
                result[key] = value
            elif first_level and key == "metadata":
                # For metadata we only copy the fields that are typically used for
                # identification (name, namespace). If the metadata is not a dict we
                # just copy it verbatim.
                if isinstance(value, dict):
                    m = {k: v for k, v in value.items() if k in ("name", "namespace")}
                    result[key] = m
                else:
                    result[key] = value
            else:
                result[key] = None

    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    result = {}
    identifying_keys = {"apiVersion", "kind"}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    new_list.append(None)
            result[key] = new_list
        else:
            if first_level and key in identifying_keys:
                result[key] = value
            else:
                result[key] = None
    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    # Identify fields that should be preserved at the top level
    ID_FIELDS = {"apiVersion", "kind", "metadata"}

    result = {}

    for key, value in manifest_dict.items():
        # Preserve full values for identifying fields on the first level
        if first_level and key in ID_FIELDS:
            # For metadata, keep only name and namespace if present
            if key == "metadata" and isinstance(value, dict):
                meta_copy = {}
                if "name" in value:
                    meta_copy["name"] = value["name"]
                if "namespace" in value:
                    meta_copy["namespace"] = value["namespace"]
                result[key] = meta_copy
            else:
                result[key] = value

        elif isinstance(value, dict):
            # Recurse into nested dicts (not first level unless explicitly set)
            result[key] = generate_default_observer_schema_dict(value, first_level=False)

        elif isinstance(value, list):
            # Recurse into list items if they are dicts; otherwise set to None
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    new_list.append(None)
            result[key] = new_list

        else:
            # Replace all primitive values with None unless preserving ID fields
            result[key] = None

    return result

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """

    for key, subschema in observer_schema.items():
        if key not in response:
            raise KeyError(f"Key '{key}' not present in response")
        if key not in last_applied_manifest:
            last_applied_manifest[key] = response[key]
        if isinstance(subschema, dict):
            if not isinstance(last_applied_manifest[key], dict):
                last_applied_manifest[key] = {}
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], subschema, response[key]
            )
        elif isinstance(subschema, list):
            if not isinstance(last_applied_manifest[key], list):
                last_applied_manifest[key] = []
            # Assuming helper to update lists exists
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[key], subschema, response[key]
            )

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for key, subschema in observer_schema.items():
        if key not in response:
            raise KeyError(f"Key {key!r} not present in response")
        if isinstance(subschema, dict):
            # Recursively process nested dicts
            if key not in last_applied_manifest:
                last_applied_manifest[key] = {}
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], subschema, response[key]
            )
        elif isinstance(subschema, list):
            # Delegate to the list‑update helper
            if key not in last_applied_manifest:
                last_applied_manifest[key] = []
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[key], subschema, response[key]
            )
        else:
            # Primitive value: set only if missing
            if key not in last_applied_manifest:
                last_applied_manifest[key] = response[key]

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_list_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated.
        observer_schema (dict): partial ``observer_schema`` describing the
            fields to observe.  Nested dictionaries signal nested objects.
            A ``list`` value indicates that the field is a list and should be
            processed by :func:`update_last_applied_manifest_list_from_resp`.
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response.
    """
    for field, schema in observer_schema.items():
        # Missing field in the response: raise error.
        if field not in response:
            raise KeyError(
                f"Observed field '{field}' not found in Kubernetes response"
            )

        # If the schema is a dict, we have a nested object.
        if isinstance(schema, dict):
            # Ensure the nested dict exists in the last applied manifest
            if field not in last_applied_manifest:
                last_applied_manifest[field] = {}
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[field], schema, response[field]
            )
        # If the schema is a list, delegate to the list‐handling function.
        elif isinstance(schema, list):
            # Ensure the list exists in the last applied manifest
            if field not in last_applied_manifest:
                last_applied_manifest[field] = []
            # The list may contain a single element schema describing the items.
            item_schema = schema[0] if schema else None
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[field], item_schema, response[field]
            )
        else:
            # Basic field: add to the manifest if it isn't already present
            if field not in last_applied_manifest:
                last_applied_manifest[field] = response[field]
    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    default_schemas = {}
    # Iterate over resources defined in the manifest
    for resource_name, resource_obj in getattr(app.spec, "manifest", {}).items():
        # Check for a custom observer schema
        custom_schema = None
        if hasattr(resource_obj, "observer_schema"):
            custom_schema = getattr(resource_obj, "observer_schema")
        elif isinstance(resource_obj, dict):
            custom_schema = resource_obj.get("observer_schema")
        if custom_schema is not None:
            default_schemas[resource_name] = custom_schema
            continue
        # Generate a simple default schema when none is provided
        default_schemas[resource_name] = {
            "metadata": {"path": "/metadata"},
            "spec": {"path": "/spec"},
            "status": {"path": "/status"},
        }
    return default_schemas

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Retrieve the manifest from the application spec
    manifest = getattr(app.spec, "manifest", None)
    if manifest is None:
        return

    # The manifest can either be a list of resource objects or a dict
    if isinstance(manifest, list):
        resources = manifest
    elif isinstance(manifest, dict):
        # Try common keys that may hold the resources
        resources = manifest.get("resources") or manifest.get("items") or []
    else:
        resources = []

    # Ensure containers for custom and default observer schemas exist
    custom_schemas = getattr(app.spec, "custom_observer_schemas", {})
    if custom_schemas is None:
        custom_schemas = {}

    default_schemas = getattr(app.spec, "default_observer_schemas", {})
    if default_schemas is None:
        default_schemas = {}

    # Iterate over resources and build defaults for those that lack a custom schema
    for resource in resources:
        if not isinstance(resource, dict):
            continue
        kind = resource.get("kind")
        if not kind:
            continue
        # Skip kinds that already have a custom observer schema specified
        if kind in custom_schemas:
            continue

        # Create a minimal default schema (empty object)
        default_schema = {
            "type": "object",
            "properties": {},
            "required": [],
        }

        default_schemas[kind] = default_schema

    # Persist the computed defaults back to the spec
    setattr(app.spec, "default_observer_schemas", default_schemas)

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the application has a spec and manifest
    if not hasattr(app, "spec") or not hasattr(app.spec, "manifest"):
        return
    # Ensure the observer_schema dictionary exists
    if not hasattr(app.spec, "observer_schema") or app.spec.observer_schema is None:
        app.spec.observer_schema = {}
    # Load the default schemas if they are defined somewhere
    default_schemas = getattr(app, "DEFAULT_OBSERVER_SCHEMAS", None)
    if default_schemas is None:
        try:
            from .defaults import DEFAULT_OBSERVER_SCHEMAS as default_schemas
        except Exception:
            default_schemas = {}
    # Iterate over resources in the manifest
    resources = getattr(app.spec.manifest, "resources", [])
    for resource in resources:
        # Support both dict-like and object-like resources
        kind = None
        if isinstance(resource, dict):
            kind = resource.get("kind")
        else:
            kind = getattr(resource, "kind", None)
        if not kind:
            continue
        # Skip if a custom schema is already defined
        if kind in app.spec.observer_schema:
            continue
        # Try to fetch a default schema for this kind
        schema = default_schemas.get(kind)
        if schema is None:
            schema = default_schemas.get("default")
        if schema is not None:
            import copy
            app.spec.observer_schema[kind] = copy.deepcopy(schema)

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the observer schema dictionary exists on the application spec
    if not hasattr(app.spec, "observer_schema") or app.spec.observer_schema is None:
        app.spec.observer_schema = {}

    # Helper function to map Python types to JSON Schema types
    def _json_type(value):
        if isinstance(value, bool):
            return "boolean"
        elif isinstance(value, int):
            return "integer"
        elif isinstance(value, float):
            return "number"
        elif isinstance(value, list):
            return "array"
        elif isinstance(value, dict):
            return "object"
        else:
            return "string"

    # Iterate over all resources in the manifest
    for resource in getattr(app.spec, "manifest", []):
        kind = resource.get("kind")
        if not kind:
            continue

        # Skip if a custom observer schema is already defined for this kind
        if kind in app.spec.observer_schema:
            continue

        # Build a simple default schema based on the fields present in the spec
        spec_fields = resource.get("spec", {})
        properties = {}
        for field_name, field_value in spec_fields.items():
            properties[field_name] = {"type": _json_type(field_value)}

        default_schema = {
            "type": "object",
            "properties": properties,
        }

        # Add the generated schema to the observer schema mapping
        app.spec.observer_schema[kind] = default_schema

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """Convert the SQL query to use the out‑style parameters instead of
    the in‑style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in‑style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    - The formatted SQL query (:class:`str` or :class:`bytes`).

    - The set of converted out‑style parameters (:class:`dict` or
      :class:`list`).

    """
    import re

    in_style = getattr(self.SQLParams, "in_style", None)
    out_style = getattr(self.SQLParams, "out_style", None)

    if in_style is None or out_style is None:
        raise ValueError("SQLParams.in_style and out_style must be defined")

    # Early exit if no conversion needed
    if in_style == out_style:
        return sql, params

    # Helper to perform replacement for named placeholders
    def replace_named(match):
        name = match.group(1)
        if out_style.startswith("%("):
            return "%({})s".format(name)
        elif out_style == ":":
            return ":" + name
        else:
            # Fallback to simple out_style replacement
            return out_style

    # Determine placeholder type and perform replacement
    if in_style == "?":
        # Positional placeholder replaced by out_style
        if isinstance(sql, bytes):
            sql_out = re.sub(b"\\?", out_style.encode() if isinstance(out_style, str) else out_style, sql)
        else:
            sql_out = re.sub(r"\?", out_style, sql)
        # For positional params no change needed
        return sql_out, params

    if in_style.startswith(":"):
        # Named in_style e.g. :name
        pattern = r":(\w+)"
        if isinstance(sql, bytes):
            # decode for regex, then encode back
            txt = sql.decode("utf-8")
            txt = re.sub(pattern, replace_named, txt)
            sql_out = txt.encode("utf-8")
        else:
            sql_out = re.sub(pattern, replace_named, sql)
        return sql_out, params

    if in_style.startswith("%(") and in_style.endswith(")s"):
        # Named in_style e.g. %(name)s
        pattern = r"%\((\w+)\)s"
        def repl_named(match):
            name = match.group(1)
            if out_style == ":":
                return ":" + name
            elif out_style in ("?", "%s"):
                return out_style
            elif out_style.startswith("%("):
                return "%({})s".format(name)
            else:
                return out_style

        if isinstance(sql, bytes):
            txt = sql.decode("utf-8")
            txt = re.sub(pattern, repl_named, txt)
            sql_out = txt.encode("utf-8")
        else:
            sql_out = re.sub(pattern, repl_named, sql)
        return sql_out, params

    # Fallback generic replacement
    if isinstance(sql, bytes):
        sql_out = re.sub(in_style.encode(), out_style.encode() if isinstance(out_style, str) else out_style, sql)
    else:
        sql_out = re.sub(in_style, out_style, sql)
    return sql_out, params

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.
    """
    import re
    from collections.abc import Mapping

    # Helper to get placeholder pattern for the current in-style
    def _replace_qmark(s):
        return s.replace("?", "%s") if isinstance(s, str) else s.replace(b"?", b"%s")

    def _replace_numeric(s):
        return (
            re.sub(r":(\d+)", "%s", s)
            if isinstance(s, str)
            else re.sub(b":(\\d+)", b"%s", s)
        )

    def _replace_named(s):
        return (
            re.sub(r":([A-Za-z_][A-Za-z0-9_]*)", "%s", s)
            if isinstance(s, str)
            else re.sub(b":([A-Za-z_][A-Za-z0-9_]*)", b"%s", s)
        )

    def _replace_pyformat(s):
        return (
            re.sub(r"%\(([A-Za-z_][A-Za-z0-9_]*)\)s", "%s", s)
            if isinstance(s, str)
            else re.sub(b"%\\(([A-Za-z_][A-Za-z0-9_]*)\\)s", b"%s", s)
        )

    # Determine the in-style for this instance
    in_style = getattr(self.SQLParams, "in_style", None)

    # Convert the SQL string
    if isinstance(sql, bytes):
        if in_style == "qmark":
            new_sql = _replace_qmark(sql)
        elif in_style == "numeric":
            new_sql = _replace_numeric(sql)
        elif in_style == "named":
            new_sql = _replace_named(sql)
        elif in_style == "pyformat":
            new_sql = _replace_pyformat(sql)
        else:
            new_sql = sql
    else:
        if in_style == "qmark":
            new_sql = _replace_qmark(sql)
        elif in_style == "numeric":
            new_sql = _replace_numeric(sql)
        elif in_style == "named":
            new_sql = _replace_named(sql)
        elif in_style == "pyformat":
            new_sql = _replace_pyformat(sql)
        else:
            new_sql = sql

    # Convert the parameters
    out_params: List[Any] = []

    # Helper to fetch ordered values for named/pyformat styles
    def _extract_named_values(params: Mapping):
        ordered = []
        if isinstance(new_sql, bytes):
            pattern = re.compile(b"[%?]*\\(([A-Za-z_][A-Za-z0-9_]*)\\)s")
        else:
            pattern = re.compile(r"[%?]*\(([A-Za-z_][A-Za-z0-9_]*)\)s")
        for match in pattern.finditer(new_sql.decode() if isinstance(new_sql, bytes) else new_sql):
            ordered.append(params[match.group(1)])
        return ordered

    for params in many_params:
        if isinstance(params, Sequence) and not isinstance(params, (str, bytes)):
            # Sequence (positional) handling – just forward as list
            out_params.append(list(params))
        elif isinstance(params, Mapping):
            # Mapping (named) handling – extract in order
            out_params.append([params[key] for key in params])
        else:
            raise TypeError(
                f"Unsupported parameter type {type(params)!r} – expected dict or sequence"
            )

    return new_sql, out_params

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Attempt to validate the OCFL object
        from ocfl import validate as ocfl_validate
        return ocfl_validate(path, allow_warnings=True)
    except Exception:
        return False

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Local filesystem path
        if isinstance(path, str) or hasattr(path, "__fspath__"):
            if not os.path.isdir(path):
                warnings.warn(f'Path {path} is not a directory')
                return False
            if not os.path.isdir(os.path.join(path, 'ocfl')):
                warnings.warn(f'OCFL root missing in {path}')
                return False
            return True
        # PyFilesystem root
        else:
            if not path.isdir('ocfl'):
                warnings.warn('OCFL root missing in pyfs root')
                return False
            return True
    except Exception as exc:
        warnings.warn(f'Error validating OCFL object: {exc}')
        return False

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Path must be provided
    if not path:
        return False

    # Path must exist and be a directory
    if not os.path.isdir(path):
        return False

    # Basic OCFL object checks – look for standard marker files
    required_files = {'.ocfl_version', '.ocfl_manifest'}
    root_files = {os.path.basename(f) for f in os.listdir(path)}
    if not required_files.issubset(root_files):
        return False

    # If more sophisticated validation is required (e.g., checksum
    # verification or structural checks), it should be called here.
    # For now, the existence of the marker files is treated as a valid
    # OCFL object.
    return True

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os
    if not path:
        return False
    try:
        if not os.path.isdir(path):
            return False
        # In OCFL, a valid root contains an "objects" directory.
        objects_root = os.path.join(path, 'objects')
        if not os.path.isdir(objects_root):
            return False
        # Iterate over each object ID directory
        for oid in os.listdir(objects_root):
            oid_path = os.path.join(objects_root, oid)
            if not os.path.isdir(oid_path):
                return False
            # Each object should have a top-level `current` directory
            current_dir = os.path.join(oid_path, 'current')
            if not os.path.isdir(current_dir):
                return False
            # There should be an inventory file (usually `manifest.csv`) in `current`
            inventory = os.path.join(current_dir, 'manifest.csv')
            if not os.path.isfile(inventory):
                return False
        return True
    except Exception:
        return False

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not path:
            return False
        if not isinstance(path, (str, os.PathLike)):
            return False
        if not os.path.isdir(path):
            return False
        # Basic OCFL structure check: must contain an 'objects' directory
        objects_dir = os.path.join(path, "objects")
        if not os.path.isdir(objects_dir):
            return False
        # Check that requested path is either the root or a valid object
        # (more thorough validation logic would go here)
        return True
    except Exception:
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    status = getattr(self, 'status', None)
    if status is None:
        return prefix
    # Prefer enum name if available; otherwise fall back to a mapping or string conversion
    if hasattr(status, 'name'):
        text = status.name
    elif hasattr(self, '_STATUS2STR'):
        text = self._STATUS2STR.get(status, str(status))
    else:
        text = str(status)
    return f"{prefix}{text}"

def status_str(self, prefix=''):
