def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # If the object does not have a `log` attribute, return an empty string
    if not hasattr(self, "log"):
        return ""

    lines = []
    for entry in self.log:
        # Entry can be a dict with `status` and optional `msg`,
        # or a plain string/tuple.
        if isinstance(entry, dict):
            status = entry.get("status", "")
            msg = entry.get("msg") or entry.get("message") or ""
            if msg:
                lines.append(f"{prefix}{status}: {msg}")
            else:
                lines.append(f"{prefix}{status}")
        else:
            lines.append(f"{prefix}{entry}")

    return "\n".join(lines)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # 1. Extract specification version from inventory type if requested
    if extract_spec_version:
        inv_type = inventory.get('type')
        if inv_type is not None:
            try:
                # Assume a mapping from type names to spec versions exists
                self.spec_version = self._spec_version_by_type(inv_type)
            except KeyError:
                # Unknown type; retain the pre-set self.spec_version
                pass

    # 2. Validate that mandatory top‑level keys exist
    for key in getattr(self, 'required_keys', ()):
        if key not in inventory:
            raise ArgumentError(key, f"Missing required key '{key}' in inventory")

    # 3. Validate each field against its specification
    for field_name, field_spec in getattr(self, 'spec', {}).items():
        if field_name not in inventory:
            # Skip optional fields
            if field_spec.get('required', False):
                raise ArgumentError(field_name, f"Field '{field_name}' is required but missing")
            continue
        value = inventory[field_name]
        self._validate_field(value, field_spec, field_name)

    # 4. Ensure there are no unknown fields
    for key in inventory:
        if key not in self.spec:
            raise ArgumentError(key, f"Unknown field '{key}' found in inventory")

    # 5. Return the validated inventory (or simply True)
    return inventory

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ValidationError("Inventory must be a dictionary")

    # Optionally extract spec version from type
    if extract_spec_version:
        type_value = inventory.get('type')
        if type_value is not None:
            try:
                self.spec_version = self._determine_spec_version(type_value)
            except ValueError:
                # If type value is not a valid spec, keep existing spec_version
                pass

    # Basic validation: ensure required structure exists for this spec version
    required = getattr(self, f"_required_fields_{self.spec_version}", set())
    missing = [field for field in required if field not in inventory]
    if missing:
        raise ValidationError(f"Missing required fields for spec {self.spec_version}: {missing}")

    # Validate individual fields
    field_specs = getattr(self, f"_field_specs_{self.spec_version}", {})
    for field, spec in field_specs.items():
        if field in inventory:
            self._validate_field(inventory[field], spec, field)
        elif spec.get('required', False):
            raise ValidationError(f"Field '{field}' is required but missing")

    return inventory

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """

        # Basic sanity check
        if not isinstance(inventory, dict):
            raise ValueError("Inventory must be a dictionary")

        # Determine the specification version
        spec_version = self.spec_version
        if extract_spec_version:
            type_val = inventory.get("type")
            if isinstance(type_val, str):
                # Map the type string to a spec version; if mapping fails, fall back
                spec_version = self.type_to_spec_map.get(type_val, self.spec_version)
            else:
                # If type is missing or not a string, use the default spec_version
                spec_version = self.spec_version

        # Validate required fields for the determined spec_version
        required = self.spec_requirements.get(spec_version, set())
        missing = required - inventory.keys()
        if missing:
            raise ValueError(f"Missing required fields for spec {spec_version}: {missing}")

        # Validate field types according to the schema for this spec_version
        field_specs = self.spec_schemas.get(spec_version, {})
        for key, spec in field_specs.items():
            if key in inventory:
                val = inventory[key]
                expected_type = spec.get("type")
                if expected_type is not None:
                    if not isinstance(val, expected_type):
                        # allow callable validators in the schema
                        if callable(expected_type):
                            if not expected_type(val):
                                raise ValueError(f"Field '{key}' failed custom validation")
                        else:
                            raise ValueError(
                                f"Field '{key}' expected type {expected_type.__name__}, "
                                f"got {type(val).__name__}"
                            )

        # If all checks passed, return the inventory unchanged
        return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    needed = set()
    for mf in manifest_files:
        # Expected that each manifest entry has a digest attribute
        digest = getattr(mf, 'digest', None) or getattr(mf, 'sha256', None)
        if digest:
            needed.add(digest)
    missing = needed - digests_used
    if missing:
        raise ValueError(f"Missing required digests: {', '.join(missing)}")
    # Optional: also warn about digests that were used but not referenced
    unused = digests_used - needed
    if unused:
        raise ValueError(f"Digests used but not referenced by manifest: {', '.join(unused)}")
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Gather the expected digests from the manifest entries
    manifest_digests = set()
    for entry in manifest_files:
        digest = None
        # Manifest entry might store the digest under different keys
        if isinstance(entry, dict):
            digest = entry.get("digest") or entry.get("fingerprint") or entry.get("sha256")
            # Preserve support for nested structures (e.g., entry["file"]["digest"])
            if not digest and "file" in entry:
                file_info = entry["file"]
                if isinstance(file_info, dict):
                    digest = file_info.get("digest") or file_info.get("fingerprint")
        else:
            # If entry is not a dict we cannot extract a digest
            raise ValueError(f"Unsupported manifest entry type: {type(entry)!r} - {entry!r}")

        if not digest:
            raise ValueError(f"Manifest entry missing digest: {entry!r}")

        manifest_digests.add(digest)

    # Ensure all required digests were listed among the used digests
    unused_in_used = digests_used.difference(manifest_digests)
    if unused_in_used:
        raise ValueError(
            f"Digests listed as used but missing from manifest: "
            f"{', '.join(sorted(unused_in_used))}"
        )

    # Ensure all digests in the manifest were used
    missing_in_used = manifest_digests.difference(digests_used)
    if missing_in_used:
        raise ValueError(
            f"Digests present in the manifest but not used: "
            f"{', '.join(sorted(missing_in_used))}"
        )

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Determine the set of digests that are actually present in this session
    if hasattr(self, "_digests") and isinstance(self._digests, (set, list, tuple)):
        present_set = set(self._digests)
    elif hasattr(self, "analyzed_files") and isinstance(self.analyzed_files, dict):
        # assume keys are digests
        present_set = set(self.analyzed_files.keys())
    else:
        # fall back to an empty set (nothing can be verified)
        present_set = set()

    missing = set()
    unused = set()

    for digest in manifest_files:
        if digest not in present_set:
            missing.add(digest)
        if digest not in digests_used:
            unused.add(digest)

    if missing:
        raise ValueError(
            f"The following digests are listed in the manifest but are not present: "
            f"{', '.join(sorted(missing))}"
        )
    if unused:
        # A digest was present but never used; warn but don't fail
        warning_msg = (
            f"The following digests are present but were not used: "
            f"{', '.join(sorted(unused))}"
        )
        # If the class has a logger, use it; otherwise fallback to print
        if hasattr(self, "log") and callable(self.log.warn):
            self.log.warn(warning_msg)
        else:
            print(warning_msg)

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Build a set of digests that the manifest expects.
    expected_digests = set()
    for path, digest in manifest_files.items():
        # Skip entries that do not specify a digest.
        if digest:
            expected_digests.add(digest)

    # Digests that are used but not expected by the manifest.
    unexpected_used = set(digests_used) - expected_digests

    # Digests that are expected by the manifest but were never used.
    not_used = expected_digests - set(digests_used)

    if unexpected_used or not_used:
        messages = []
        if unexpected_used:
            messages.append(
                f"Digests used but not present in manifest: "
                f"{', '.join(sorted(unexpected_used))}"
            )
        if not_used:
            files = [path for path, ds in manifest_files.items() if ds in not_used]
            messages.append(
                f"Digests required by manifest but not used: "
                f"{', '.join(sorted(files))}"
            )
        raise ValueError("; ".join(messages))

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Make sure the prior object is of the same type
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an {type(self).__name__} instance, got {type(prior).__name__}")

    # Verify that the prior is actually older (by version or timestamp)
    if hasattr(self, "version") and hasattr(prior, "version"):
        if prior.version >= self.version:
            raise ValueError(f"Prior inventory version {prior.version} is not older than current version {self.version}")
    elif hasattr(self, "timestamp") and hasattr(prior, "timestamp"):
        if prior.timestamp >= self.timestamp:
            raise ValueError(f"Prior inventory timestamp {prior.timestamp} is not older than current timestamp {self.timestamp}")

    def _compare_attribute(name):
        """Compare two attributes of the current and prior inventories."""
        try:
            curr_val = getattr(self, name)
            prior_val = getattr(prior, name)
        except AttributeError:
            # If either attribute is missing, skip this check
            return

        # If the attribute has a shape/rows/cols, compare those
        if hasattr(curr_val, "shape"):
            if curr_val.shape != prior_val.shape:
                raise ValueError(f"Attribute '{name}' shape mismatch: current {curr_val.shape}, prior {prior_val.shape}")
        elif hasattr(curr_val, "rows") and hasattr(curr_val, "cols"):
            if (curr_val.rows, curr_val.cols) != (prior_val.rows, prior_val.cols):
                raise ValueError(f"Attribute '{name}' size mismatch: current ({curr_val.rows},{curr_val.cols}), prior ({prior_val.rows},{prior_val.cols})")
        # For iterable collections, compare the sets of items
        elif isinstance(curr_val, (list, tuple, set, dict)):
            if set(curr_val) != set(prior_val):
                raise ValueError(f"Attribute '{name}' content mismatch between current and prior inventories.")
        else:
            if curr_val != prior_val:
                raise ValueError(f"Attribute '{name}' values differ between current and prior inventories.")

    # Attributes that should match exactly
    for attr in ("species", "propensities", "stoichiometry_matrix"):
        _compare_attribute(attr)

    # Ensure that the prior does not reference any new species or propensities
    def _check_subset(attr):
        try:
            curr_set = set(getattr(self, attr))
            prior_set = set(getattr(prior, attr))
        except AttributeError:
            return
        if not prior_set.issubset(curr_set):
            missing = prior_set - curr_set
            raise ValueError(f"Prior inventory's '{attr}' contains {missing} not present in current inventory.")

    for attr in ("species", "propensities"):
        _check_subset(attr)

    # All checks passed
    return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # ensure prior is the same type
    if not isinstance(prior, type(self)):
        raise TypeError('Prior must be an InventoryValidator instance')

    # parameters and species in prior must be a subset of the current inventory
    prior_params = set(prior.parameters)
    prior_species = set(prior.species)

    missing_params = prior_params - set(self.parameters)
    if missing_params:
        raise ValueError(f'Prior contains parameters not present in current inventory: {missing_params}')

    missing_species = prior_species - set(self.species)
    if missing_species:
        raise ValueError(f'Prior contains species not present in current inventory: {missing_species}')

    # Compare stoichiometry for species present in both inventories
    curr_index = {s: i for i, s in enumerate(self.species)}
    prior_index = {s: i for i, s in enumerate(prior.species)}
    for s in prior_species & set(self.species):
        curr_row = self.stoichiometry_matrix[curr_index[s]]
        prior_row = prior.stoichiometry_matrix[prior_index[s]]
        if not np.array_equal(curr_row, prior_row):
            raise ValueError(f"Stoichiometry row for species {s!r} differs between current and prior inventory")

    # Ensure propensities in prior are a subset of the current propensities
    # We compare by shape and content of each propensity row
    if prior.propensities.shape[0] > self.propensities.shape[0]:
        raise ValueError('Prior contains more propensity rows than current inventory')
    # Check that each prior propensity row appears in the current inventory
    for i, prior_row in enumerate(prior.propensities):
        match_found = False
        for j, curr_row in enumerate(self.propensities):
            if np.array_equal(prior_row, curr_row):
                match_found = True
                break
        if not match_found:
            raise ValueError(f'Prior propensity row {i} is not present in the current inventory')

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for logical_path, entry in inventory.items():
        files = set()

        if isinstance(entry, dict):
            # Direct file reference
            if "file" in entry:
                files.add(entry["file"])

            # Versioned file list: dict of version -> file(s)
            if "files" in entry and isinstance(entry["files"], dict):
                for ver, file_obj in entry["files"].items():
                    # Include files for the target version or any later version
                    try:
                        if ver == version or ver > version:
                            if isinstance(file_obj, (list, set, tuple)):
                                files.update(file_obj)
                            else:
                                files.add(file_obj)
                    except Exception:
                        # If comparison fails, fall back to include all
                        if isinstance(file_obj, (list, set, tuple)):
                            files.update(file_obj)
                        else:
                            files.add(file_obj)

            # If entry contains an iterable of files directly
            if isinstance(entry, (list, set, tuple)):
                files.update(entry)

        elif isinstance(entry, (list, set, tuple)):
            files.update(entry)

        else:
            # Non-iterable entry is treated as a singular file path
            files.add(entry)

        logical_path_map[logical_path] = files

    return logical_path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Determine the logical paths that exist in the requested version
    logical_paths = set()
    current_items = inventory.get(version, [])
    for item in current_items:
        lp = item.get('logical_path_in_state')
        if lp is not None:
            logical_paths.add(lp)

    # Build the map by collecting all files that correspond to these logical paths
    path_map = {}
    for ver, items in inventory.items():
        for item in items:
            lp = item.get('logical_path_in_state')
            if lp in logical_paths:
                path_map.setdefault(lp, set()).add(item.get('content_file'))
    return path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    def _parse_version(v):
        """Return a tuple that can be used for simple ordering comparison.

        Non‑numeric parts are treated as smaller than any numeric suffix
        (e.g. '0.0.1a1' is considered earlier than '0.0.2').
        """
        parts = []
        for part in v.split("."):
            try:
                parts.append(int(part))
            except ValueError:
                # strip any trailing non‑digit suffix
                digits = ""
                for ch in part:
                    if ch.isdigit():
                        digits += ch
                    else:
                        break
                parts.append(int(digits) if digits else 0)
        return tuple(parts)

    def _is_later(v):
        """Return True if version v is later than the requested `version`."""
        try:
            return _parse_version(v) > _parse_version(version)
        except Exception:
            # Fallback: compare lexicographically
            return v > version

    result = {}
    for logical_path, data in inventory.items():
        files = set()

        # Case 1: `data` is a mapping from versions to file paths
        if isinstance(data, dict) and all(isinstance(k, str) for k in data.keys()):
            for v, file_path in data.items():
                if v == version or _is_later(v):
                    files.add(file_path)

        # Case 2: `data` is a list of dictionaries containing `version` and `file`
        elif isinstance(data, list):
            for entry in data:
                v = entry.get("version")
                if v is None:
                    continue
                if v == version or _is_later(v):
                    files.add(entry.get("file"))

        # Case 3: legacy single entry mapping with `content` key
        elif isinstance(data, dict) and "content" in data:
            for item in data["content"]:
                v = item.get("version")
                if v is None:
                    continue
                if v == version or _is_later(v):
                    files.add(item.get("file"))

        if files:
            result[logical_path] = files

    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    path_map = {}
    for ver, mapping in inventory.items():
        # mapping is expected to be a dict of logical_path -> content_file
        for logical_path, content_file in mapping.items():
            path_map.setdefault(logical_path, set()).add(content_file)
    return path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dict")

    # The block must contain a list of files
    if 'files' not in fixity:
        raise ValueError("Missing 'files' key in fixity block")
    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' must be a list")

    # Validate each entry
    seen_paths = set()
    for entry in files:
        if not isinstance(entry, dict):
            raise ValueError("Each entry in 'files' must be a dict")
        if 'path' not in entry:
            raise ValueError("Each file entry must contain a 'path' key")
        if 'checksum' not in entry:
            raise ValueError("Each file entry must contain a 'checksum' key")

        path = entry['path']

        # Ensure only files from the manifest are referenced
        if path not in manifest_files:
            raise ValueError(f"Fixity references file not in manifest: {path}")

        # Avoid duplicate references
        if path in seen_paths:
            raise ValueError(f"Duplicate path in fixity block: {path}")
        seen_paths.add(path)

    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure fixity is a mapping of file names to checksums
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary mapping file to checksum")
    # Ensure manifest_files is a set for efficient lookup
    if not isinstance(manifest_files, set):
        try:
            manifest_files = set(manifest_files)
        except TypeError:
            raise ValueError("Manifest files must be a list, tuple, or set of file names")
    # Files referenced in fixity must all be present in the manifest
    unknown_files = [fn for fn in fixity if fn not in manifest_files]
    if unknown_files:
        raise ValueError(f"Fixity references unknown files: {unknown_files}")
    # Basic check of checksum values (must be non-empty strings)
    for fn, chksum in fixity.items():
        if not isinstance(chksum, str) or not chksum:
            raise ValueError(f"Checksum for file '{fn}' must be a non-empty string")
    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")

    files = fixity.get("files")
    if files is None:
        raise ValueError("Missing 'files' key in fixity block.")
    if not isinstance(files, list):
        raise ValueError("'files' in fixity block must be a list.")

    seen_paths = set()
    for entry in files:
        if not isinstance(entry, dict):
            raise ValueError("Each entry in 'files' must be a dictionary.")
        required_keys = {"path", "hash", "algorithm"}
        missing = required_keys - entry.keys()
        if missing:
            raise ValueError(
                f"Fixity file entry missing keys: {', '.join(sorted(missing))}"
            )

        path = entry["path"]
        if path not in manifest_files:
            raise ValueError(
                f"Path '{path}' referenced in fixity block is not present in the manifest."
            )
        if path in seen_paths:
            raise ValueError(f"Duplicate path '{path}' found in fixity block.")
        seen_paths.add(path)

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

