    file_name = fixity["file"]
    if not isinstance(file_name, str):
        raise ValueError("'file' entry must be a string")

    # The file referenced must be present in the manifest
    if file_name not in manifest_files:
        raise ValueError(f"Fixity references unknown file '{file_name}'")

    # Optional keys with expected types
    if "size" in fixity and not isinstance(fixity["size"], int):
        raise ValueError("'size' must be an integer")
    if "sha256" in fixity and not isinstance(fixity["sha256"], str):
        raise ValueError("'sha256' must be a string")
    if "md5" in fixity and not isinstance(fixity["md5"], str):
        raise ValueError("'md5' must be a string")

    # Disallow any unexpected keys
    allowed_keys = {"file", "size", "sha256", "md5"}
    for key in fixity:
        if key not in allowed_keys:
            raise ValueError(f"Unexpected key in fixity block: '{key}'")

    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary mapping file names to hash dictionaries")

    manifest_set = set(manifest_files)

    for fname, hashes in fixity.items():
        if fname not in manifest_set:
            raise ValueError(f"Fixity references unknown file: {fname}")

        if not isinstance(hashes, dict):
            raise ValueError(f"Hashes for file {fname} must be a dictionary of algorithm names to checksum strings")

        if not hashes:
            raise ValueError(f"No hashes provided for file {fname}")

        for algo, digest in hashes.items():
            if not isinstance(algo, str) or not isinstance(digest, str):
                raise ValueError(f"Invalid hash entry for {fname}: {algo!r} -> {digest!r}")

    return True

