def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    data = {}
    for entry in os.listdir(folder):
        full_path = os.path.join(folder, entry)
        if not os.path.isfile(full_path):
            continue

        base, ext = os.path.splitext(entry)
        if base not in data:
            data[base] = {"xml": None, "files": []}

        if ext.lower() == ".xml":
            try:
                with open(full_path, "r", encoding="utf-8") as f:
                    data[base]["xml"] = f.read()
            except Exception:
                data[base]["xml"] = None
        else:
            data[base]["files"].append(full_path)

    return data

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    packages = {}
    xml_basenames = set()
    for root, _, files in os.walk(folder):
        for f in files:
            if f.lower().endswith('.xml'):
                base = os.path.splitext(f)[0]
                xml_basenames.add(base)
    for root, _, files in os.walk(folder):
        for f in files:
            base = os.path.splitext(f)[0]
            if base in xml_basenames:
                path = os.path.join(root, f)
                packages.setdefault(base, []).append(path)
    return packages

def add_rendition(self, lang, file_path):
    """
    Add a rendition for a given language.

    Example mapping after addition:
        {
            "original": "artigo02.pdf",
            "en": "artigo02-en.pdf",
        }
    """
    # Ensure the renditions dictionary exists on this instance.
    if not hasattr(self, "renditions"):
        self.renditions = {}

    # Store the path for the requested language.
    self.renditions[lang] = file_path

    # If the "original" key is not already present, assume the first
    # file added for any language is the original.
    if "original" not in self.renditions:
        # Keep only the filename without directory components.
        self.renditions["original"] = os.path.basename(file_path)

    return self.renditions

