def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    base_indent = ' ' * indent

    def _pp(obj):
        if isinstance(obj, dict):
            if not obj:
                return "{}"
            items = []
            for k, v in obj.items():
                items.append(f"{k!r}: {_pp(v)}")
            return "{ " + ", ".join(items) + " }"
        elif isinstance(obj, (list, tuple, set)):
            if not obj:
                return "[]" if isinstance(obj, list) else "()" if isinstance(obj, tuple) else "{}"
            items = ", ".join(_pp(i) for i in obj)
            if isinstance(obj, tuple):
                return f"({items})"
            elif isinstance(obj, set):
                return f"{{{items}}}"
            return f"[{items}]"
        elif hasattr(obj, "__dict__"):
            attrs = {k: v for k, v in vars(obj).items() if not k.startswith('_')}
            if debug:
                return f"<{type(obj).__name__} {attrs}>"
            return f"{type(obj).__name__}({attrs})"
        else:
            return repr(obj)

    return base_indent + _pp(self)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if debug:
        return f"<{self.__class__.__name__} id={id(self)}>"
    try:
        # Attempt to JSON-serialize the object, falling back to its __dict__
        import json
        return json.dumps(self, default=lambda o: o.__dict__, indent=indent, sort_keys=True)
    except Exception:
        return repr(self)

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    import pprint
    if debug:
        return f"{self.__class__.__name__} details: {pprint.pformat(self.__dict__, indent=indent)}"
    return pprint.pformat(self, indent=indent)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    op = getattr(self, 'op', None)
    if op not in ('&', '|'):
        # nothing to do if we don't know the operator
        return list(args)

    res = list(args)

    # Work with copies to avoid mutation during iteration
    for a in res[:]:
        for b in res[:]:
            if a is b:
                continue
            # We need to work only with expression objects that have .op and .args
            op_b = getattr(b, 'op', None)
            args_b = getattr(b, 'args', None)
            if op_b not in ('|', '&') or args_b is None:
                continue

            # helper to check if a is in the arguments of an expression
            def contains_expr(expr, target):
                return target in getattr(expr, 'args', ())

            if op == '&':  # for absorption A & (A | B)
                if op_b == '|' and contains_expr(b, a):
                    res.remove(b)
                    break
                # negative absorption A & (~A | B) = A & B
                if op_b == '|':
                    neg_a = None
                    for p in args_b:
                        if getattr(p, 'op', None) == '~':
                            sub = getattr(p, 'args', ())
                            if len(sub) == 1 and sub[0] is a:
                                neg_a = p
                                break
                    if neg_a:
                        rest = [p for p in args_b if p is not neg_a]
                        if rest:
                            res.remove(b)
                            for r in rest:
                                if r not in res:
                                    res.append(r)
            elif op == '|':  # for absorption A | (A & B)
                if op_b == '&' and contains_expr(b, a):
                    res.remove(b)
                    break
                # negative absorption A | (~A & B) = A | B
                if op_b == '&':
                    neg_a = None
                    for p in args_b:
                        if getattr(p, 'op', None) == '~':
                            sub = getattr(p, 'args', ())
                            if len(sub) == 1 and sub[0] is a:
                                neg_a = p
                                break
                    if neg_a:
                        rest = [p for p in args_b if p is not neg_a]
                        if rest:
                            res.remove(b)
                            for r in rest:
                                if r not in res:
                                    res.append(r)
    return res

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # ---------- helper functions ----------
    def tokenize(expr):
        """Return a list of tokens from the expression string."""
        tokens = []
        i = 0
        while i < len(expr):
            c = expr[i]
            if c.isspace():
                i += 1
                continue
            if c in "()&|~":
                tokens.append(c)
                i += 1
            else:
                # read a variable / symbol (letters, numbers, underscores)
                j = i
                while j < len(expr) and (expr[j].isalnum() or expr[j] == "_"):
                    j += 1
                tokens.append(expr[i:j])
                i = j
        return tokens

    def parse_expression(tokens):
        """Parse tokens into a nested tuple structure.
        Return tuple (node, remaining_tokens).
        Node format:
            ('VAR', name)             -- variable
            ('NOT', subnode)          -- not
            ('AND', left, right)      -- and
            ('OR', left, right)       -- or
        """
        def parse_primary(ts):
            if not ts:
                raise ValueError("Unexpected end of expression")
            tok = ts[0]
            if tok == '(':
                sub, rest = parse_expression(ts[1:])
                if not rest or rest[0] != ')':
                    raise ValueError("Missing closing parenthesis")
                return sub, rest[1:]
            elif tok == '~':
                sub, rest = parse_primary(ts[1:])
                return ('NOT', sub), rest
            else:
                # variable
                return ('VAR', tok), ts[1:]

        def parse_factor(ts):
            node, ts = parse_primary(ts)
            while ts and ts[0] == '&':
                right, ts = parse_primary(ts[1:])
                node = ('AND', node, right)
            return node, ts

        node, ts = parse_factor(tokens)
        while ts and ts[0] == '|':
            right, ts = parse_factor(ts[1:])
            node = ('OR', node, right)
        return node, ts

    def parse(tokens):
        node, rest = parse_expression(tokens)
        if rest:
            raise ValueError(f"Unexpected tokens: {rest}")
        return node

    # ---------- simplification functions ----------
    def node_equal(a, b):
        if a[0] != b[0]:
            return False
        if a[0] == 'VAR':
            return a[1] == b[1]
        if a[0] == 'NOT':
            return node_equal(a[1], b[1])
        return node_equal(a[1], b[1]) and node_equal(a[2], b[2])

    def contains(expr, target):
        """Return True if expr tree contains a node equal to target."""
        if node_equal(expr, target):
            return True
        if expr[0] in ('AND', 'OR'):
            return contains(expr[1], target) or contains(expr[2], target)
        if expr[0] == 'NOT':
            return contains(expr[1], target)
        return False

    def drop_not(node, target_var):
        """Given a node (OR or AND) containing a NOT target_var, drop that NOT and
           return a new node without that part."""
        if node[0] == 'OR':
            left, right = node[1], node[2]
            # if either side is NOT(target_var), remove that side
            if node_equal(left, ('NOT', ('VAR', target_var))):
                return right
            if node_equal(right, ('NOT', ('VAR', target_var))):
                return left
            # otherwise recurse
            new_left = drop_not(left, target_var)
            new_right = drop_not(right, target_var)
            return ('OR', new_left, new_right)
        if node[0] == 'AND':
            left, right = node[1], node[2]
            new_left = drop_not(left, target_var)
            new_right = drop_not(right, target_var)
            return ('AND', new_left, new_right)
        return node

    def simplify(node):
        """Recursively apply absorption and negative absorption rules."""
        if node[0] in ('VAR', 'NOT'):
            return node
        # simplify children first
        left = simplify(node[1])
        right = simplify(node[2])
        # check patterns when node is AND
        if node[0] == 'AND':
            # A & (A | B) => A
            if right[0] == 'OR':
                if node_equal(left, right[1]):
                    return left
                if node_equal(left, right[2]):
                    return left
                # negative absorption: A & (~A | B) => A & B
                if right[1][0] == 'NOT' and node_equal(left, right[1][1]):
                    return ('AND', left, right[2])
                if right[2][0] == 'NOT' and node_equal(left, right[2][1]):
                    return ('AND', left, right[1])
            # symmetrical case A | (A & B) => A
            if right[0] == 'AND':
                if node_equal(left, right[1]):
                    return left
                if node_equal(left, right[2]):
                    return left
                # negative absorption: A | (~A & B) => A | B
                if right[1][0] == 'NOT' and node_equal(left, right[1][1]):
                    return ('OR', left, right[2])
                if right[2][0] == 'NOT' and node_equal(left, right[2][1]):
                    return ('OR', left, right[1])
            # Also check when left contains patterns
            # e.g., (A | B) & A -> A
            if left[0] == 'OR':
                if node_equal(right, left[1]) or node_equal(right, left[2]):
                    return right
                if left[1][0] == 'NOT' and node_equal(right, left[1][1]):
                    return ('AND', right, left[2])
                if left[2][0] == 'NOT' and node_equal(right, left[2][1]):
                    return ('AND', right, left[1])
            if left[0] == 'AND':
                if node_equal(right, left[1]) or node_equal(right, left[2]):
                    return right
                if left[1][0] == 'NOT' and node_equal(right, left[1][1]):
                    return ('OR', right, left[2])
                if left[2][0] == 'NOT' and node_equal(right, left[2][1]):
                    return ('OR', right, left[1])
        # reconstruct node with simplified children
        return (node[0], left, right)

    def node_to_str(node):
        if node[0] == 'VAR':
            return node[1]
        if node[0] == 'NOT':
            sub = node[1]
            if sub[0] in ('AND', 'OR'):
                return f"~({node_to_str(sub)})"
            else:
                return f"~{node_to_str(sub)}"
        if node[0] == 'AND':
            left, right = node[1], node[2]
            left_str = node_to_str(left)
            right_str = node_to_str(right)
            if left[0] == 'OR':
                left_str = f"({left_str})"
            if right[0] == 'OR':
                right_str = f"({right_str})"
            return f"{left_str} & {right_str}"
        if node[0] == 'OR':
            left, right = node[1], node[2]
            left_str = node_to_str(left)
            right_str = node_to_str(right)
            return f"{left_str} | {right_str}"
        raise ValueError(f"Unknown node type: {node[0]}")

    # ---------- apply to each expression ----------
    transformed = []
    for expr_str in args:
        try:
            tokens = tokenize(expr_str)
            tree = parse(tokens)
            simplified_tree = simplify(tree)
            simplified_str = node_to_str(simplified_tree)
            transformed.append(simplified_str)
        except Exception:
            # If parsing or simplification fails, keep original
            transformed.append(expr_str)
    return transformed

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner_func

