def get_versions(default="unknown"):
    """Get version information or return default if unable to do so."""
    try:
        # Python 3.8+
        from importlib.metadata import version
    except ImportError:
        try:
            # Backport for older Python versions
            from importlib_metadata import version
        except ImportError:
            return default

    # Prefer the package name if this module is part of a package,
    # otherwise fall back to the module's name.
    pkg_name = __package__ or __name__
    try:
        return version(pkg_name)
    except Exception:
        return default

def get_versions():
    """Get version information or return default if unable to do so."""
    DEFAULT = 'unknown'
    try:
        import importlib.metadata as importlib_metadata
        return importlib_metadata.version(__name__)
    except Exception:
        return DEFAULT

def get_versions():
    """Get version information or return default if unable to do so."""
    import sys
    versions = {}
    for name, module in sys.modules.items():
        try:
            version = getattr(module, "__version__", None)
            if version is None:
                continue
            versions[name] = str(version)
        except Exception:
            versions[name] = "unknown"
    return versions

