def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, (list, tuple)):
        commands = [commands]
    env_vars = os.environ.copy()
    if env:
        env_vars.update(env)
    for cmd in commands:
        full_cmd = [cmd] + args
        if verbose and not hide_stderr:
            print("Command:", " ".join(full_cmd))
        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env_vars,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT if not hide_stderr else subprocess.PIPE,
                text=True,
            )
            if result.returncode != 0:
                raise RuntimeError(
                    f"Command '{cmd}' failed with exit code {result.returncode}"
                )
            if verbose:
                print(result.stdout)
            return result.stdout.strip()
        except FileNotFoundError:
            continue
    raise FileNotFoundError(f"Could not find any of the commands: {commands}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Resolve the command sequence
    if isinstance(commands, str):
        import shlex
        cmd = shlex.split(commands)
    else:
        cmd = list(commands)

    # Append any additional arguments
    if args:
        cmd.extend(args)

    # Prepare subprocess arguments
    import subprocess
    kwargs = {
        'stdout': subprocess.PIPE,
        'stderr': subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
        'cwd': cwd,
        'env': env,
    }

    try:
        proc = subprocess.Popen(cmd, **kwargs)
        out, err = proc.communicate()

        if proc.returncode != 0:
            raise RuntimeError(f"Command {cmd!r} exited with status {proc.returncode}")

        # If verbose, echo the command output
        if verbose:
            import sys
            if out:
                sys.stdout.write(out.decode() if isinstance(out, bytes) else str(out))
            if not hide_stderr and err:
                sys.stderr.write(err.decode() if isinstance(err, bytes) else str(err))

        return out

    except FileNotFoundError as exc:
        raise RuntimeError(f"Command not found: {cmd[0]}") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to run command {cmd!r}: {exc}") from exc

