def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version or not version.isdigit():
        return ""
    new_num = int(version) + 1
    new_str = str(new_num)
    if len(new_str) < len(version):
        # Preserve original zero padding
        return new_str.rjust(len(version), "0")
    return new_str

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ""

    parts = version.split(".")
    try:
        nums = [int(p) for p in parts]
    except ValueError:
        # If any part is not numeric, return original
        return version

    # Increment the last numeric component
    nums[-1] += 1

    # Preserve original widths for zero-prefixed segments
    new_parts = []
    for orig, new_val in zip(parts, nums):
        # Determine pad width: keep leading zeros if present
        pad_width = len(orig) if orig.startswith("0") else 0
        if pad_width:
            new_parts.append(f"{new_val:0{pad_width}d}")
        else:
            new_parts.append(str(new_val))

    return ".".join(new_parts)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ""

    parts = version.split('.')
    new_parts = []
    for i, part in enumerate(parts):
        if i == len(parts) - 1:  # increment the last component
            try:
                num = int(part)
                incremented = num + 1
                # Preserve zero-padding if present and width > 1
                if part.startswith('0') and len(part) > 1:
                    new_part = str(incremented).zfill(len(part))
                else:
                    new_part = str(incremented)
            except ValueError:
                # Non-numeric part: leave unchanged
                new_part = part
        else:
            new_part = part
        new_parts.append(new_part)
    return '.'.join(new_parts)

def next_version(version):
