            raise ValueError(f"'files' entry must be a mapping in {dir_name}")
        # First inventory becomes the root reference
        if i == 0:
            root_inventory = files_map
            continue
        # Compare digests against the root inventory
        for path, digest in files_map.items():
            root_digest = root_inventory.get(path)
            if digest != root_digest:
                differences.setdefault(path, []).append((i, digest, root_digest))
        # Optional: ensure no new files appear that are missing from root (you can adjust logic)
        for path in root_inventory.keys():
            if path not in files_map:
                differences.setdefault(path, []).append((i, None, root_inventory[path]))
    self._inventory_differences = differences
    return differences

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    if not os.path.exists(path):
        return f'path does not exist'

    # If the path is a file, return 'file'
    if os.path.isfile(path):
        return 'file'

    # If the path is a directory, look for Namaste files
    if os.path.isdir(path):
        try:
            for name in os.listdir(path):
                if name.startswith('0='):
                    full = os.path.join(path, name)
                    try:
                        with open(full, 'rb') as f:
                            content = f.read().strip()
                        # Interpret content as ASCII/UTF-8 bytes
                        try:
                            text = content.decode('utf-8')
                        except Exception:
                            text = content.decode('latin1')
                        if text.startswith('OCFL/Root'):
                            return 'root'
                        if text.startswith('OCFL/Container'):
                            return 'object'
                    except Exception:
                        continue
            # No recognizable Namaste file
            return 'unknown directory'
        except Exception as e:
            return f'error reading directory: {e}'

    # Not a file or directory: treat as invalid
    return 'invalid path'

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not path:
        return "invalid path"
    if os.path.isfile(path):
        return "file"
    if os.path.isdir(path):
        try:
            entries = os.listdir(path)
        except Exception as exc:
            return f"error reading directory: {exc}"
        # Check for "0=*" files directly within this directory
        for entry in entries:
            full_path = os.path.join(path, entry)
            if os.path.isfile(full_path) and entry.startswith("0="):
                return "root"
        # If no "0=*" file here, check subdirectories for such a file
        for entry in entries:
            sub_path = os.path.join(path, entry)
            if os.path.isdir(sub_path):
                try:
                    sub_entries = os.listdir(sub_path)
                except Exception:
                    continue
                for sub_entry in sub_entries:
                    sub_full = os.path.join(sub_path, sub_entry)
                    if os.path.isfile(sub_full) and sub_entry.startswith("0="):
                        return "object"
        return "unknown directory"
    return f"not a directory nor file: {path}"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    # Verify the input path
    if not path:
        return "error: empty path"

    # Handle files directly
    if hasattr(os.path, "isfile") and os.path.isfile(path):
        return "file"

    # Handle non-existent paths
    if hasattr(os.path, "exists") and not os.path.exists(path):
        return "error: path does not exist"

    # Path must be a directory at this point
    if hasattr(os.path, "isdir") and not os.path.isdir(path):
        return "error: path is not a file or directory"

    # Find Namaste files (pattern 0=*)
    try:
        namaste_files = [f for f in os.listdir(path) if f.startswith("0=")]
    except Exception as e:
        return f"error: cannot list directory contents: {e}"

    if not namaste_files:
        return "error: no Namaste file found"
    if len(namaste_files) > 1:
        return "error: multiple Namaste files found"

    # Read the Namaste file content
    namaste_path = os.path.join(path, namaste_files[0])
    try:
        with open(namaste_path, "r", encoding="utf-8") as fh:
            content = fh.read().lower()
    except Exception as e:
        return f"error: cannot read Namaste file: {e}"

    # Determine path type from file content
    if "root" in content or "storage root" in content:
        return "root"
    if "object" in content:
        return "object"

    return "error: unknown Namaste file content"

