def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def _is_mapping(node):
        return getattr(node, 'tag', None) and node.tag.startswith('tag:yaml.org,2002:map')

    def _merge_nodes(a, b):
        # Return later node if not both mappings
        if not (_is_mapping(a) and _is_mapping(b)):
            return b
        # Both are mappings: recursively merge
        merged = {}
        for k, v in a.value:
            merged[k.value] = (k, v)
        for k, v in b.value:
            key_id = k.value
            if key_id in merged:
                existing_k, existing_v = merged[key_id]
                merged[key_id] = (existing_k, _merge_nodes(existing_v, v))
            else:
                merged[key_id] = (k, v)
        # Preserve order of first occurrence
        return type(a)(tag=a.tag, value=[(k, v) for k, v in merged.values()])

    merged_dict = {}
    for key_node, val_node in nodes:
        key_id = key_node.value
        if key_id in merged_dict:
            _, existing_val = merged_dict[key_id]
            merged_dict[key_id] = (merged_dict[key_id][0], _merge_nodes(existing_val, val_node))
        else:
            merged_dict[key_id] = (key_node, val_node)
    return [(key, val) for key, val in merged_dict.values()]

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def merge_mapping_nodes(node1, node2):
        # Assume both are ruamel.yaml.nodes.MappingNode
        new_items = list(node1.value)
        for k2, v2 in node2.value:
            key2 = k2.value
            found = False
            for idx, (k_old, v_old) in enumerate(new_items):
                if k_old.value == key2:
                    # Merge if both values are MappingNode, otherwise override
                    if isinstance(v_old, node1.__class__) and isinstance(v2, node2.__class__):
                        new_items[idx] = (k_old, merge_mapping_nodes(v_old, v2))
                    else:
                        new_items[idx] = (k_old, v2)
                    found = True
                    break
            if not found:
                new_items.append((k2, v2))
        return node1.__class__(tag=node1.tag, value=new_items)

    merged = {}
    key_nodes = {}
    for k_node, v_node in nodes:
        key = k_node.value
        if key not in merged:
            merged[key] = v_node
            key_nodes[key] = k_node
        else:
            existing = merged[key]
            if isinstance(existing, ruamel.yaml.nodes.MappingNode) and isinstance(v_node, ruamel.yaml.nodes.MappingNode):
                merged[key] = merge_mapping_nodes(existing, v_node)
            else:
                merged[key] = v_node
                key_nodes[key] = k_node
    return [(key_nodes[k], merged[k]) for k in merged]

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    def is_mapping(node):
        return hasattr(node, 'tag') and node.tag.endswith(':map')

    def merge_mapping_nodes(node_a, node_b):
        """
        Merge two MappingNode objects and return a new MappingNode.
        """
        merged_map = {}
        merged_list = []
        # Combine the two mapping entries
        combined = node_a.value + node_b.value
        for k, v in combined:
            key_str = k.as_string() if hasattr(k, 'as_string') else str(k)
            if key_str in merged_map:
                existing_k, existing_v = merged_map[key_str]
                if is_mapping(existing_v) and is_mapping(v):
                    merged_val = merge_mapping_nodes(existing_v, v)
                    merged_map[key_str] = (existing_k, merged_val)
                else:
                    merged_map[key_str] = (existing_k, v)
            else:
                merged_map[key_str] = (k, v)
        # Preserve the original order of the first occurrence
        for key_str in merged_map:
            merged_list.append(merged_map[key_str])
        return type(node_a)(tag=node_a.tag, value=merged_list)

    final = {}
    for key, value in nodes:
        key_str = key.as_string() if hasattr(key, 'as_string') else str(key)
        if key_str in final:
            existing_key, existing_val = final[key_str]
            if is_mapping(existing_val) and is_mapping(value):
                merged_val = merge_mapping_nodes(existing_val, value)
                final[key_str] = (existing_key, merged_val)
            else:
                final[key_str] = (existing_key, value)
        else:
            final[key_str] = (key, value)
    return list(final.values())

def deep_merge_nodes(nodes):
    def merge_mapping_nodes(m_node_a, m_node_b):
        a_list = m_node_a.value
        b_list = m_node_b.value
        key_to_index = {k.value: idx for idx, (k, _) in enumerate(a_list)}
        result = a_list[:]
        for k_b, v_b in b_list:
            key = k_b.value
            if key in key_to_index:
                idx = key_to_index[key]
                v_a = result[idx][1]
                if isinstance(v_a, nodes.MappingNode) and isinstance(v_b, nodes.MappingNode):
                    result[idx] = (result[idx][0], merge_mapping_nodes(v_a, v_b))
                else:
                    result[idx] = (result[idx][0], v_b)
            else:
                result.append((k_b, v_b))
        return nodes.MappingNode(m_node_a.tag, result)

    merged_dict = {}
    first_keys = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key not in merged_dict:
            merged_dict[key] = value_node
            first_keys[key] = key_node
        else:
            existing = merged_dict[key]
            if isinstance(existing, nodes.MappingNode) and isinstance(value_node, nodes.MappingNode):
                merged_dict[key] = merge_mapping_nodes(existing, value_node)
            else:
                merged_dict[key] = value_node

    seen = set()
    result = []
    for key_node, _ in nodes:
        key = key_node.value
        if key not in seen:
            seen.add(key)
            result.append((first_keys[key], merged_dict[key]))
    return result

