def deep_merge_nodes(nodes):
    """
    Deep merge a list of YAML nodes, each represented as a tuple of
    (ScalarNode, value_node).

    Args:
        nodes (Iterable[Tuple[ScalarNode, Node]]): A sequence of two-item
            tuples where the first element is a ScalarNode key and the
            second element is the associated value node, which can be a
            MappingNode or any other YAML node.

    Returns:
        List[Tuple[ScalarNode, Node]]: The merged list. Duplicate keys are
        merged recursively if the corresponding values are MappingNodes;
        otherwise the last value wins.
    """
    def merge_mapping_nodes(m1, m2):
        """Recursively merge two MappingNode objects."""
        # Build a dict for the first mapping
        merged = {}
        for k_node, v_node in m1.value:
            key = k_node.value
            merged[key] = (k_node, v_node)

        # Override / add from the second mapping
        for k_node, v_node in m2.value:
            key = k_node.value
            if key in merged:
                old_k_node, old_v_node = merged[key]
                if isinstance(old_v_node, MappingNode) and isinstance(v_node, MappingNode):
                    merged[key] = (old_k_node, merge_mapping_nodes(old_v_node, v_node))
                else:
                    merged[key] = (k_node, v_node)
            else:
                merged[key] = (k_node, v_node)

        # Preserve original ordering: first take keys from m1 (in order),
        # then any remaining keys from m2 (in order)
        result = []
        seen = set()
        for k_node, v_node in m1.value:
            key = k_node.value
            if key in merged:
                _, merged_val = merged[key]
                result.append((k_node, merged_val))
                seen.add(key)
        for k_node, v_node in m2.value:
            key = k_node.value
            if key not in seen and key in merged:
                _, merged_val = merged[key]
                result.append((k_node, merged_val))
                seen.add(key)
            elif key not in seen:
                result.append((k_node, v_node))
                seen.add(key)

        return MappingNode(m1.tag, value=result)

    key_map = {}
    for key_node, val_node in nodes:
        key = key_node.value
        if key in key_map:
            existing_key_node, existing_val_node = key_map[key]
            if isinstance(existing_val_node, MappingNode) and isinstance(val_node, MappingNode):
                merged_val = merge_mapping_nodes(existing_val_node, val_node)
                key_map[key] = (existing_key_node, merged_val)
            else:
                # last value wins
                key_map[key] = (key_node, val_node)
        else:
            key_map[key] = (key_node, val_node)

    # Preserve insertion order of unique keys
    result = []
    for key in key_map:
        result.append(key_map[key])
    return result

