    Given command-line arguments with which this script was invoked, parse the arguments
    and return them as an ArgumentParser instance.
    """
    import argparse

    parser = argparse.ArgumentParser(
        description='Command-line interface to the script.'
    )

    # Add any desired arguments here. For example:
    parser.add_argument(
        '-v', '--verbose', action='store_true',
        help='Increase output verbosity'
    )
    parser.add_argument(
        '-o', '--output', metavar='FILE',
        help='Specify output file'
    )
    parser.add_argument(
        'positional', nargs='*',
        help='Positional arguments'
    )

    if arguments:
        # Flatten the tuple of arguments into a single list of strings
        args = [a for arg in arguments for a in arg]
        return parser.parse_args(args)
    else:
        return parser.parse_args()

def parser_flags(parser):
