def bash_completion():
    '''Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.'''
    from borgmatic.cli import main as borg_group
    from click_completion import get_completion
    return get_completion('bash', borg_group)

def bash_completion():
    """Return a bash completion script for the borgmatic command."""
    import click
    from borgmatic.cli import borg as cli

    def collect_options(cmd):
        """Return a list of option strings for a click.Command or Group."""
        opts = []
        for param in cmd.params:
            if param.param_type_name == "option":
                opts.extend([opt for opt in param.opts if opt.startswith("-")])
        return opts

    # Gather top‑level command names
    commands = list(cli.commands.keys())

    # Build Bash *case* entry for each subcommand, listing its options
    case_entries = ""
    for name, subcmd in cli.commands.items():
        opts = collect_options(subcmd)
        if opts:
            opt_opts = " ".join(opts)
            case_entries += f'    {name} () {{ \\n'
            case_entries += f'        COMPREPLY=( $(compgen -W "{opt_opts}" -- "$cur") ); \\n'
            case_entries += f'    }}\\n'
        else:
            case_entries += f'    {name} () {{ :; }}\\n'

    script = f"""
_borgmatic_completion() {{
    local cur prev words cword
    _init_completion || return

    # Subcommand completions (first argument)
    if [ ${{COMP_CWORD}} -eq 1 ]; then
        COMPREPLY=( $(compgen -W "{' '.join(commands)}" -- "$cur") )
        return 0
    fi

    local sub=${{COMP_WORDS[1]}}
    case "$sub" in
{case_entries}    *)
        ;;
    esac
}}
complete -F _borgmatic_completion borgmatic
"""
    return script.strip()

