def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        try:
            return int(size)
        except Exception:
            return 0
    size = size.strip()
    if not size:
        return 0

    # Regular expression to parse numeric part and unit.
    import re
    m = re.fullmatch(r'(?P<num>[\d\.]+)\s*(?P<unit>[kKmMgGtTpP]?)', size)
    if not m:
        # If pattern doesn't match, try to interpret as integer.
        try:
            return int(float(size))
        except Exception:
            return 0

    number = float(m.group('num'))
    unit = m.group('unit').lower()

    multipliers = {
        '': 1,
        'k': 1_000,
        'm': 1_000_000,
        'g': 1_000_000_000,
        't': 1_000_000_000_000,
        'p': 1_000_000_000_000_000,
    }
    factor = multipliers.get(unit, 1)
    return int(round(number * factor))

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    import re

    size = size.strip()
    m = re.match(r'^([0-9]*\.?[0-9]+)\s*([bBkmgtpyez]*[bB]?)?$', size)
    if not m:
        raise ValueError(f"Invalid size format: {size}")

    number = float(m.group(1))
    unit = (m.group(2) or '').lower()

    if unit in ("", "b", "bytes"):
        multiplier = 1
    elif unit in ("k", "kb"):
        multiplier = 1000
    elif unit in ("m", "mb"):
        multiplier = 1000**2
    elif unit in ("g", "gb"):
        multiplier = 1000**3
    elif unit in ("t", "tb"):
        multiplier = 1000**4
    elif unit in ("p", "pb"):
        multiplier = 1000**5
    elif unit in ("e", "eb"):
        multiplier = 1000**6
    elif unit in ("z", "zb"):
        multiplier = 1000**7
    elif unit in ("y", "yb"):
        multiplier = 1000**8
    else:
        raise ValueError(f"Unknown unit: {unit}")

    return int(round(number * multiplier))

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for k, v in d.items():
            result[k] = result.get(k, 0) + v
    return result

