    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    from collections import defaultdict

    totals = defaultdict(int)
    for d in dicts:
        if d:  # skip None or empty dict
            for key, value in d.items():
                totals[key] += value
    return dict(totals)

