def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''

    import re
    pattern = re.compile(r'\{([^\}]+)\}')
    def _repl(match):
        key = match.group(1)
        return str(url_args.get(key, match.group(0)))
    return pattern.sub(_repl, url)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return url

    if not url_args:
        return url

    pattern = r"{([a-zA-Z0-9_]+)}"

    def _repl(match):
        key = match.group(1)
        if key in url_args:
            value = url_args[key]
            if value is None:
                value = ''
            else:
                value = str(value)
            return urllib.parse.quote(value, safe='')
        return match.group(0)

    return re.sub(pattern, _repl, url)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args

    Args:
        url (str): The URL containing placeholders formatted as `{key}`.
        url_args (Mapping[str, Any]): Mapping of placeholder keys to the
            values that should replace them. Values will be URL‑encoded
            before substitution.

    Returns:
        str: URL with all placeholders replaced by the corresponding
        values from ``url_args``.
    """
    if not url_args:
        return url

    import re
    import urllib.parse

    def _encode_value(val):
        return urllib.parse.quote(str(val), safe="")

    # Find all occurrences of {key} in the URL and replace them if the key
    # exists in url_args. Any key not present in url_args is left unchanged.
    def replace_match(match):
        key = match.group(1)
        if key in url_args:
            return _encode_value(url_args[key])
        return match.group(0)

    return re.sub(r"\{(\w+)\}", replace_match, url)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url:
        return url
    if not url_args:
        return url

    # Replace placeholders in the form {key} with the corresponding value from url_args.
    for key, value in url_args.items():
        placeholder = f'{{{key}}}'
        url = url.replace(placeholder, str(value))

    return url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''
    if not url_args:
        return url

    for key, value in url_args.items():
        # Ensure value is string
        replace_value = str(value)
        # Replace placeholder formats like {key} or :key
        url = url.replace('{' + key + '}', replace_value)
        url = url.replace(':' + key, replace_value)

    return url

