def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("alphabet must contain at least one character")

    base = len(alphabet)

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        while number:
            number, rem = divmod(number, base)
            digits.append(alphabet[rem])
        result = "".join(reversed(digits))

    if negative:
        result = "-" + result

    if padding is not None:
        if padding < 0:
            raise ValueError("padding cannot be negative")
        pad_len = padding - len(result)
        if pad_len > 0:
            pad_char = alphabet[0]
            # If negative sign present, pad after the sign
            if result[0] == "-":
                result = "-" + (pad_char * pad_len) + result[1:]
            else:
                result = (pad_char * pad_len) + result

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("number must be non-negative")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two characters")
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        result = ''.join(reversed(digits))
    if padding is not None:
        if len(result) < padding:
            result = alphabet[0] * (padding - len(result)) + result
    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("negative numbers not supported")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two symbols")
    # Special case for zero
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while number:
            number, rem = divmod(number, base)
            digits.append(alphabet[rem])
        digits.reverse()
    if padding is not None:
        if padding < len(digits):
            raise ValueError(f"padding {padding} is less than the number of digits {len(digits)}")
        pad_count = padding - len(digits)
        digits = [alphabet[0]] * pad_count + digits
    return ''.join(digits)

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    """
    def _replace_in_obj(obj):
        if isinstance(obj, dict):
            # Replace key if it matches register_value
            if register_value in obj:
                obj[register_number] = obj.pop(register_value)
            # Recursively process all values
            for k, v in list(obj.items()):
                _replace_in_obj(v)
        elif isinstance(obj, list):
            for item in obj:
                _replace_in_obj(item)

    _replace_in_obj(flow_params)
    return flow_params

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    :return: The updated flow_params dictionary
    """
    def _replace_recursive(obj):
        if isinstance(obj, dict):
            for key, val in obj.items():
                if key == register_value:
                    obj[key] = register_number
                else:
                    _replace_recursive(val)
        elif isinstance(obj, list):
            for item in obj:
                _replace_recursive(item)

    for flow_name, flow in flow_params.items():
        _replace_recursive(flow)

    return flow_params

