def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    stack = [cls]
    while stack:
        c = stack.pop()
        seen.add(c)
        for sub in c.__subclasses__():
            if sub not in seen:
                stack.append(sub)
    seen.discard(cls)
    return seen

