def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    # Determine platform if needed
    if platform == 'this':
        plat = 0 if sys.platform.startswith('win') else 1
    else:
        plat = platform

    if plat == 1:
        # POSIX shlex-like regex
        pattern = r'''(?:"([^"\\]*(?:\\.[^"\\]*)*)"|'([^'\\]*(?:\\.[^'\\]*)*)'|(\S+))'''
    else:
        # Windows CMD shlex-like regex
        pattern = r'''(?:"([^"\\]*(?:\\.[^"\\]*)*)"|'([^'\\]*(?:\\.[^'\\]*)*)'|([^\\s]+))'''
    tokens = []
    for m in re.finditer(pattern, s):
        tok = m.group(1) or m.group(2) or m.group(3)
        tokens.append(tok)
    return tokens

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Uses fast REGEX when
    available but falls back to shlex.split for correctness.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import os
    import shlex

    # Resolve platform value
    if platform == 'this':
        platform = 0 if os.name == 'nt' else 1

    # POSIX: regular shlex with posix=True
    if platform == 1:
        return shlex.split(s, posix=True)

    # Windows: regular shlex with posix=False
    if platform == 0:
        return shlex.split(s, posix=False)

    # Fallback for unexpected values: try POSIX, then Windows
    try:
        return shlex.split(s, posix=True)
    except ValueError:
        return shlex.split(s, posix=False)

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list,
    sort the list for only ignored files, return those files as a single
    string with each filename separated by a comma."""
    try:
        output = subprocess.check_output(
            ["git", "ls-files", "--others", "--ignored", "--exclude-standard"],
            stderr=subprocess.STDOUT
        )
        files = output.decode("utf-8").strip().splitlines()
