def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None:
        return None
    if isinstance(frequency, str):
        freq = frequency.strip().lower()
        if freq == "always":
            return None
    else:
        raise ValueError("Frequency must be a string, None, or 'always'")

    import re
    match = re.match(r'^(?P<num>\d+)\s*(?P<unit>\w+)$', freq)
    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency}")

    num = int(match.group('num'))
    unit = match.group('unit')

    unit_map = {
        'second': 'seconds',
        'seconds': 'seconds',
        'minute': 'minutes',
        'minutes': 'minutes',
        'hour': 'hours',
        'hours': 'hours',
        'day': 'days',
        'days': 'days',
        'week': 'weeks',
        'weeks': 'weeks',
        'month': 'days',
        'months': 'days',
    }

    if unit not in unit_map:
        raise ValueError(f"Unrecognized time unit: {unit}")

    if unit in ('month', 'months'):
        # approximate a month as 30 days
        return datetime.timedelta(days=num * 30)

    kwargs = {unit_map[unit]: num}
    return datetime.timedelta(**kwargs)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or (isinstance(frequency, str) and frequency.strip().lower() == 'always'):
        return None

    if not isinstance(frequency, str):
        raise ValueError('frequency must be a string')

    freq = frequency.strip()
    parts = freq.split()
    if len(parts) != 2:
        raise ValueError(f'cannot parse frequency: {frequency!r}')

    num_str, unit = parts
    if not num_str.isdigit():
        raise ValueError(f'cannot parse number: {num_str!r}')

    value = int(num_str)
    unit = unit.lower()

    mapping = {
        'day': 'days', 'days': 'days', 'd': 'days',
        'hour': 'hours', 'hours': 'hours', 'h': 'hours',
        'minute': 'minutes', 'minutes': 'minutes', 'min': 'minutes', 'm': 'minutes',
        'second': 'seconds', 'seconds': 'seconds', 's': 'seconds',
        'week': 'weeks', 'weeks': 'weeks', 'w': 'weeks',
    }

    if unit not in mapping:
        raise ValueError(f'unknown unit {unit!r}')

    kwargs = {mapping[unit]: value}
    return datetime.timedelta(**kwargs)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    if isinstance(frequency, str):
        freq_str = frequency.strip().lower()
        if not freq_str or freq_str == 'always':
            return None
    else:
        raise ValueError('frequency must be a string, None, or "always"')

    import re
    m = re.match(r'^(\d+)\s*(\w+)$', freq_str)
    if not m:
        raise ValueError(f"Cannot parse frequency: '{frequency}'")

    number, unit = int(m.group(1)), m.group(2)
    # Normalize unit by removing trailing 's' if present
    if unit.endswith('s'):
        unit = unit.rstrip('s')
    # Mapping from unit to timedelta keyword
    unit_map = {
        'second': 'seconds',
        'minute': 'minutes',
        'hour': 'hours',
        'day': 'days',
        'week': 'weeks',
        'millisecond': 'milliseconds',
        'microsecond': 'microseconds',
    }
    # Special handling for months and years (approximate)
    if unit in ('month',):
        # Assume 30 days per month
        return datetime.timedelta(days=number * 30)
    if unit in ('year',):
        # Assume 365 days per year
        return datetime.timedelta(days=number * 365)

    if unit not in unit_map:
        raise ValueError(f"Unrecognized time unit: '{unit}'")

    kwargs = {unit_map[unit]: number}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            addr = sockaddr[0]
            if family == socket.AF_INET and addr == '127.0.0.1':
                return True
            if family == socket.AF_INET6 and addr in ('::1', '0:0:0:0:0:0:0:1'):
                return True
    except socket.gaierror:
        return False
    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Resolve host to a list of address info tuples
        addr_infos = socket.getaddrinfo(host, None, 0, 0, 0)
    except socket.gaierror:
        # If the hostname cannot be resolved, it cannot be localhost
        return False

    for family, _, _, _, sockaddr in addr_infos:
        ip = sockaddr[0]
        # IPv4 loopback check
        if family == socket.AF_INET:
            # 127.0.0.0/8 is the loopback network
            if ip.startswith("127."):
                return True
        # IPv6 loopback check
        elif family == socket.AF_INET6:
            # ::1 is the canonical IPv6 loopback address
            if ip == "::1":
                return True
            # IPv4-mapped IPv6 loopback (e.g., ::ffff:127.0.0.1)
            if ip.startswith("::ffff:127.0.0.1"):
                return True

    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False

    # Direct hostname check
    if str(host).lower() == 'localhost':
        return True

    try:
        infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False

    for family, _, _, _, sockaddr in infos:
        ip = sockaddr[0]
        if family == socket.AF_INET:
            # IPv4 loopback range: 127.0.0.0/8
            if ip.startswith('127.'):
                return True
        elif family == socket.AF_INET6:
            # IPv6 loopback address
            if ip == '::1':
                return True
    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Common loopback identifiers
    loopback_hosts = {"localhost", "127.0.0.1", "::1"}
    if host in loopback_hosts:
        return True
    try:
        for info in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = info
            if family == socket.AF_INET and sockaddr[0] == "127.0.0.1":
                return True
            if family == socket.AF_INET6 and sockaddr[0] == "::1":
                return True
    except socket.gaierror:
