    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Resolve host to addresses. ``port`` is irrelevant here, so use None.
        for res in socket.getaddrinfo(host, None, proto=socket.IPPROTO_TCP):
            sockaddr = res[4]
            # For IPv6, ``sockaddr`` is a tuple of (address, port, flowinfo, scopeid).
            # For IPv4, it's (address, port).
            ip = sockaddr[0]
            if ':' in ip:
                # IPv6 loopback
                if ip.lower() == '::1':
                    return True
            else:
                # IPv4 loopback
                if ip.startswith('127.'):
                    return True
        return False
    except socket.gaierror:
        # Could not resolve hostname; treat as not local
        return False

