def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    cmd_parts = []

    # Accept a single command as a string or a list of strings or a list of lists
    if isinstance(commands, str):
        cmd_parts.append(commands)
    elif isinstance(commands, (list, tuple)):
        for cmd in commands:
            if isinstance(cmd, (list, tuple)):
                cmd_parts.extend(cmd)
            else:
                cmd_parts.append(cmd)
    else:
        raise TypeError("commands must be a str, list, or tuple")

    # Append args if they are provided
    if args:
        if isinstance(args, str):
            cmd_parts.append(args)
        elif isinstance(args, (list, tuple)):
            cmd_parts.extend(args)
        else:
            raise TypeError("args must be a str, list, or tuple")

    # Set up stderr handling
    stderr_option = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    # Run the command
    result = subprocess.run(
        cmd_parts,
        cwd=cwd,
        env=env,
        stdout=subprocess.PIPE,
        stderr=stderr_option,
        text=True
    )

    # Optional verbose output
    if verbose:
        print("Command:", " ".join(cmd_parts))
        print("Output:", result.stdout.strip())
        if not hide_stderr and result.stderr:
            print("Error:", result.stderr.strip())

    return result

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        cmd = [commands]
    if args:
        if isinstance(args, (list, tuple)):
            cmd.extend(args)
        else:
            cmd.append(str(args))

    if verbose:
        print(f"Running command: {' '.join(cmd)}")

    # Choose where to send stderr
    stderr = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr,
            text=True,
            check=True,
        )
        if verbose:
            print(result.stdout)
        return result.stdout
    except subprocess.CalledProcessError as e:
        msg = f"Command '{' '.join(cmd)}' failed with exit code {e.returncode}"
        if verbose:
            print(msg)
        raise RuntimeError(msg) from e

