def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    x = np.array(x)
    return np.exp(-0.5 * ((x - 0.2) / 0.1) ** 2) / (0.1 * np.sqrt(2 * np.pi))

def gaussian(x):
    """Gaussian centered around 0.2 with a sigma of 0.1."""
    mu = 0.2
    sigma = 0.1
    return (1/(sigma*np.sqrt(2*np.pi)))*np.exp(-((x - mu)**2)/(2*sigma**2))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
        - dict of configuration filename to corresponding parsed configuration,
        - sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = {}
    error_records = []

    def _resolve_env_in_dict(d):
        """Recursively replace strings containing $VAR or ${VAR} with environment values."""
        if isinstance(d, dict):
            return {k: _resolve_env_in_dict(v) for k, v in d.items()}
        elif isinstance(d, list):
            return [_resolve_env_in_dict(v) for v in d]
        elif isinstance(d, str):
            import os
            try:
                # Simple shell-style expansion
                return os.path.expandvars(d)
            except Exception:
                return d
        else:
            return d

    for fname in config_filenames:
        try:
            with open(fname, 'r') as fd:
                raw = fd.read()
            # Attempt parsing based on file extension
            if fname.lower().endswith('.toml'):
                cfg = toml.loads(raw)
            elif fname.lower().endswith(('.yaml', '.yml')):
                cfg = yaml.safe_load(raw)
            else:
                # Fallback to YAML as a generic parser
                cfg = yaml.safe_load(raw)
            if overrides:
                cfg.update(overrides)
            if resolve_env:
                cfg = _resolve_env_in_dict(cfg)
            configs[fname] = cfg
        except Exception as exc:
            # Create a LogRecord for each failure
            import sys
            rec = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f"Failed to load '{fname}': {exc}",
                args=(),
                exc_info=sys.exc_info()
            )
            error_records.append(rec)

    return configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
        dict of configuration filename to corresponding parsed configuration,
        and sequence of logging.LogRecord instances containing any parse errors.
    """
    parsed_configs = {}
    error_records = []

    for filename in config_filenames:
        if not os.path.isfile(filename):
            record = logging.LogRecord(
                name="load_configurations",
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg="File does not exist: %s" % filename,
                args=None,
                exc_info=None,
            )
            error_records.append(record)
            continue

        try:
            with open(filename, "r") as f:
                if filename.lower().endswith((".yaml", ".yml")):
                    data = yaml.safe_load(f)
                elif filename.lower().endswith(".json"):
                    data = json.load(f)
                elif filename.lower().endswith(".toml"):
                    data = toml.load(f)
                else:
                    # Default to YAML if unknown extension
                    data = yaml.safe_load(f)

            if not isinstance(data, dict):
                record = logging.LogRecord(
                    name="load_configurations",
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg="Parsed configuration is not a dict: %s" % type(data),
                    args=None,
                    exc_info=None,
                )
                error_records.append(record)
                continue

            # Merge overrides if provided
            if overrides:
                data.update(overrides)

            # Resolve environment variables inside string values recursively
            if resolve_env:

                def _resolve(val):
                    if isinstance(val, str):
                        return os.path.expandvars(val)
                    if isinstance(val, dict):
                        return {k: _resolve(v) for k, v in val.items()}
                    if isinstance(val, list):
                        return [_resolve(v) for v in val]
                    return val

                data = _resolve(data)

            parsed_configs[filename] = data

        except Exception as exc:
            record = logging.LogRecord(
                name="load_configurations",
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg="Error parsing configuration file: %s" % exc,
                args=None,
                exc_info=(type(exc), exc, exc.__traceback__),
            )
            error_records.append(record)

    return parsed_configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configs = {}
    errors = []
    import os
    import json
    import yaml
    import toml

    for fn in config_filenames:
        try:
            with open(fn, 'r') as f:
                content = f.read()
            ext = os.path.splitext(fn)[1].lower()
            if ext == '.json':
                parsed = json.loads(content)
            elif ext in ('.yaml', '.yml'):
                parsed = yaml.safe_load(content)
            elif ext == '.toml':
                parsed = toml.loads(content)
            else:
                raise ValueError(f'Unsupported file extension: {ext}')
            if not isinstance(parsed, dict):
                raise ValueError('Configuration is not a dictionary')
            if overrides:
                parsed.update(overrides)

            if resolve_env:
                def expand(obj):
                    if isinstance(obj, str):
                        return os.path.expandvars(obj)
                    elif isinstance(obj, dict):
                        return {k: expand(v) for k, v in obj.items()}
                    elif isinstance(obj, list):
                        return [expand(v) for v in obj]
                    return obj
                parsed = expand(parsed)

            configs[fn] = parsed
        except Exception as e:
            record = logging.LogRecord(
                name='config',
                level=logging.ERROR,
                pathname=fn,
                lineno=0,
                msg=f'Failed to load {fn}: {e}',
                args=None,
                exc_info=None
            )
            errors.append(record)

    return configs, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import os
    import json
    from logging import makeRecord
    results = {}
    error_records = []
    # Attempt to import yaml if available
    try:
        import yaml
    except Exception:
        yaml = None

    logger_name = 'config_loader'
    for cfg_file in config_filenames:
        try:
            if not os.path.isfile(cfg_file):
                raise FileNotFoundError(f"Configuration file '{cfg_file}' does not exist")
            with open(cfg_file, 'r') as fd:
                data = fd.read()
                if yaml and (cfg_file.endswith('.yaml') or cfg_file.endswith('.yml')):
                    cfg = yaml.safe_load(data)
                else:
                    try:
                        cfg = json.loads(data)
                    except Exception:
                        # Try to load as text and keep as string if not JSON
                        cfg = data
        except Exception as exc:
            # Build a LogRecord to capture the error
            rec = makeRecord(
                name=logger_name,
                level=40,  # logging.ERROR
                pathname=cfg_file,
                lineno=0,
                msg=f"Error loading configuration '{cfg_file}': {exc}",
                args=(),
                exc_info=exc.__traceback__
            )
            error_records.append(rec)
            continue

        # Optional environmental variable resolution
        if resolve_env and isinstance(cfg, dict):
            def resolve_value(val):
                if isinstance(val, str) and ('${' in val or '$' in val):
                    try:
                        return os.path.expandvars(val)
                    except Exception:
                        return val
                return val

            def recurse(obj):
                if isinstance(obj, dict):
                    return {k: recurse(resolve_value(v)) for k, v in obj.items()}
                elif isinstance(obj, list):
                    return [recurse(resolve_value(v)) for v in obj]
                else:
                    return resolve_value(obj)

            cfg = recurse(cfg)

        # Apply overrides if provided
        if overrides and isinstance(overrides, dict):
            if not isinstance(cfg, dict):
                cfg = {}
            cfg.update(overrides)

        results[cfg_file] = cfg

    return results, error_records

