def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Fast‑path for built‑in sequence types (except str/bytes, which we treat specially)
    if isinstance(seq, (list, tuple, set, frozenset)):
        return seq, type(seq)

    # Strings and bytes are iterable but are usually treated as raw data
    if isinstance(seq, (str, bytes)):
        return seq, type(seq)

    # Arbitrary iterable (not string/bytes) – return as is
    if hasattr(seq, "__iter__"):
        return seq, type(seq)

    # File‑like object: read its contents
    if hasattr(seq, "read"):
        # If a file‑path string was accidentally treated as file‑like (i.e. a string without 'read')
        # then the following will raise and be caught below.
        data = seq.read()
        return data, type(seq)

    # Fallback: treat the object as a single element sequence
    return [seq], list

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    seq_type = type(seq)
    # If seq is already a list or tuple, return it directly
    if isinstance(seq, (list, tuple)):
        return (list(seq), seq_type)
    # If seq is a string or bytes, keep it as is
    if isinstance(seq, (str, bytes)):
        return (seq, seq_type)
    # For other iterable types, convert to a list
    try:
        if bufsize is None:
            return (list(seq), seq_type)
        # Read the iterable in chunks of size bufsize
        out = []
        it = iter(seq)
        while True:
            chunk = []
            for _ in range(bufsize):
                try:
                    chunk.append(next(it))
                except StopIteration:
                    break
            if not chunk:
                break
            out.extend(chunk)
        return (out, seq_type)
    except TypeError:
        raise TypeError(f"Object of type {seq_type.__name__} is not iterable and cannot be converted to a sequence.")

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type)."""
    # If seq is already a sequence type (string, bytes, or list/tuple), return it.
    if isinstance(seq, (str, bytes, bytearray)):
        return seq, type(seq)
    if isinstance(seq, (list, tuple)):
        return seq, type(seq)
    # For other iterable types, convert to a list and return.
    try:
        seq_list = list(seq)
    except TypeError:
        raise TypeError("Provided seq is not an iterable sequence")
    return seq_list, list

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a recognized sequence type (excluding strings)
    if isinstance(seq, (list, tuple, set, frozenset)):
        return seq, type(seq).__name__
    # Strings are treated as singular objects for this utility
    if isinstance(seq, str):
        return list(seq), "string"
    # If seq is not iterable, wrap it in a list
    try:
        iter(seq)
    except TypeError:
        return [seq], type(seq).__name__
    # seq is iterable but not a string
    if bufsize is None:
        derived_seq = list(seq)
    else:
        derived_seq = []
        for _ in range(bufsize):
            try:
                derived_seq.append(next(iter(seq)))
            except StopIteration:
                break
    return derived_seq, type(seq).__name__

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a sequence type (list or tuple) we keep it.
    if isinstance(seq, (list, tuple)):
        return (seq, type(seq).__name__)

    # If seq is file-like, read it (optionally limited by bufsize)
    if hasattr(seq, "read"):
        data = seq.read(bufsize) if bufsize is not None else seq.read()
        # Return the data as a list of characters (or bytes) and label it as 'file'
        return (list(data), "file")

    # If seq is iterable but not a list/tuple (e.g., generator, range)
    try:
        iterable = list(seq)
    except TypeError:
        # seq is not iterable: return it unchanged and mark as 'non-iterable'
        return (seq, "non-iterable")

    # For other iterables we return the list and annotate with its type name
    return (iterable, type(seq).__name__)

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    if other is None:
        return getattr(self, "_scale", None)

    # Validate that other is numeric
    if not isinstance(other, (int, float)):
        raise TypeError("Scale value must be numeric.")

    # Current scale value
    current_scale = getattr(self, "_scale", None)
    if current_scale is None or current_scale == 0:
        raise LenaValueError("Graph has unknown or zero scale; cannot rescale.")

    factor = other / current_scale

    # Rescale data: only the last coordinate
    if hasattr(self, "data"):
        # Assume data is a NumPy array or list of coordinates
        try:
            # Try NumPy-style indexing
            self.data[:, -1] *= factor
        except Exception:
            # Fallback to list-of-lists
            for i, point in enumerate(self.data):
                if len(point) > 0:
                    pt = list(point)
                    pt[-1] *= factor
                    self.data[i] = pt

    # Rescale associated errors, if any
    if hasattr(self, "errors"):
        for key, err in self.errors.items():
            # Expect errors parallel to data points
            try:
                err[:, -1] *= factor
            except Exception:
                for i, e in enumerate(err):
                    if len(e) > 0:
                        err_i = list(e)
                        err_i[-1] *= factor
                        self.errors[key][i] = err_i

    # Update the stored scale value
    self._scale = other
    return self

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Identify bin edges attribute.
    if hasattr(hist, "edges"):
        edges = hist.edges
    elif hasattr(hist, "bin_edges"):
        edges = hist.bin_edges
    else:
        raise AttributeError("Histogram must provide 'edges' or 'bin_edges'.")
    if len(edges) < 2:
        raise ValueError("Histogram edges must contain at least two values.")
    # Determine the coordinate for each bin.
    if get_coordinate == "left":
        coords = edges[:-1]
    elif get_coordinate == "right":
        coords = edges[1:]
    elif get_coordinate == "middle":
        coords = [(l + r) / 2 for l, r in zip(edges[:-1], edges[1:])]
    else:
        raise ValueError("get_coordinate must be 'left', 'right' or 'middle'.")
    # Obtain bin contents.
    if hasattr(hist, "bins"):
        bins = hist.bins
    elif hasattr(hist, "counts"):
        bins = hist.counts
    else:
        raise AttributeError("Histogram must provide 'bins' or 'counts'.")
    if len(coords) != len(bins):
        raise ValueError("Number of edges and bins differ.")
    # Construct graph points.
    points = []
    for coord, bin_val in zip(coords, bins):
        if make_value is None:
            values = (bin_val,)
        else:
            values = make_value(bin_val)
            if not isinstance(values, (tuple, list)):
                values = (values,)
        if len(values) + 1 != len(field_names):
            raise ValueError(
                "make_value returned %d values, but field_names has %d entries."
                % (len(values), len(field_names))
            )
        point = {name: val for name, val in zip(field_names, (coord,) + values)}
        points.append(point)
    # Build the final graph data structure.
    graph = {"points": points}
    # Include scale information if requested.
    if scale is True and hasattr(hist, "scale"):
        graph["scale"] = hist.scale
    elif scale is not None:
        graph["scale"] = scale
    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.  *make_value* accepts a single value
    (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be ``"left"`` (default), ``"right"`` and ``"middle"``.

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph as a list of dictionaries, one per point.
    """
    if make_value is None:
        make_value = lambda bin_: bin_
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")
    # Prepare output container
    points = []
    # Determine how to iterate over histogram bins
    # Case 1: histogram is a dict mapping key to bin content
    if isinstance(hist, dict):
        # Assume key is coordinate tuple
        for coord, bin_content in hist.items():
            # Locate coordinate - if multiple dimensions, pick first name as 'x'
            if isinstance(coord, (list, tuple)):
                coordinate = coord[0]
            else:
                coordinate = coord
            val = make_value(bin_content)
            if isinstance(val, (tuple, list)):
                if len(val) != len(field_names) - 1:
                    raise ValueError(
                        f"make_value returned {len(val)} values, "
                        f"but field_names expects {len(field_names)-1}"
                    )
                point = {field_names[0]: coordinate}
                for name, v in zip(field_names[1:], val):
                    point[name] = v
            else:
                point = {field_names[0]: coordinate, field_names[1]: val}
            points.append(point)
        return points
    # Case 2: histogram is a numpy.histogram tuple (counts, bin_edges)
    if isinstance(hist, tuple) and len(hist) == 2 and hasattr(hist[1], "__iter__"):
        counts, edges = hist
        counts = list(counts)
        edges = list(edges)
        # Determine coordinate based on get_coordinate
        if get_coordinate == "left":
            fun = lambda i: edges[i]
        elif get_coordinate == "right":
            fun = lambda i: edges[i + 1]
        else:  # middle
            fun = lambda i: (edges[i] + edges[i + 1]) / 2.0
        for i, bin_content in enumerate(counts):
            coordinate = fun(i)
            val = make_value(bin_content)
            if isinstance(val, (tuple, list)):
                if len(val) != len(field_names) - 1:
                    raise ValueError(
                        f"make_value returned {len(val)} values, "
                        f"but field_names expects {len(field_names)-1}"
                    )
                point = {field_names[0]: coordinate}
                for name, v in zip(field_names[1:], val):
                    point[name] = v
            else:
                point = {field_names[0]: coordinate, field_names[1]: val}
            points.append(point)
        return points
    # Case 3: histogram has 'counts' attribute (e.g., a custom object)
    if hasattr(hist, "counts") and hasattr(hist, "scale"):
        # Try to use histogram's scale to get coordinates
        try:
            scale_obj = getattr(hist, "scale")
            # Assume scale_obj has a method get_bin_edge or something
            bin_edges = scale_obj.bin_edges  # typical attribute
            counts = hist.counts
            if not isinstance(bin_edges, (list, tuple)):
                raise AttributeError
            if get_coordinate == "left":
                cfun = lambda i: bin_edges[i]
            elif get_coordinate == "right":
                cfun = lambda i: bin_edges[i + 1]
            else:  # middle
                cfun = lambda i: (bin_edges[i] + bin_edges[i + 1]) / 2.0
            for i, bin_content in enumerate(counts):
                coordinate = cfun(i)
                val = make_value(bin_content)
                if isinstance(val, (tuple, list)):
                    if len(val) != len(field_names) - 1:
                        raise ValueError(
                            f"make_value returned {len(val)} values, "
                            f"but field_names expects {len(field_names)-1}"
                        )
                    point = {field_names[0]: coordinate}
                    for name, v in zip(field_names[1:], val):
                        point[name] = v
                else:
                    point = {field_names[0]: coordinate, field_names[1]: val}
                points.append(point)
            return points
        except Exception:
            pass
    # If we reach here, we cannot interpret the histogram
    raise TypeError(
        f"Unsupported histogram type {type(hist)!r}. "
        "Expected dict, numpy.histogram tuple, or object with 'counts' and 'scale'."
    )

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be ``"left"`` (default), ``"right"`` and ``"middle"``.

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    if make_value is None:
        make_value = lambda bin_: bin_

    # Determine coordinate index
    if get_coordinate == "left":
        coord_offset = 0.0
    elif get_coordinate == "right":
        coord_offset = 1.0
    elif get_coordinate == "middle":
        coord_offset = 0.5
    else:
        raise ValueError(f'get_coordinate must be one of "left", "right" or "middle", got {get_coordinate}')

    # Extract bin edges and values
    if hasattr(hist, "bins"):
        edges = list(hist.bins)
    elif hasattr(hist, "edges"):
        edges = list(hist.edges)
    elif hasattr(hist, "bin_edges"):
        edges = list(hist.bin_edges)
    else:
        raise AttributeError("Histogram object must have a 'bins' (or equivalent) attribute")

    if hasattr(hist, "values"):
        values = list(hist.values)
    elif hasattr(hist, "content"):
        values = list(hist.content)
    elif hasattr(hist, "data"):
        # Assume each entry is numeric or a tuple (numeric, ctx)
        values = [entry[0] if isinstance(entry, (list, tuple)) else entry for entry in hist.data]
    else:
        # Fallback: assume iterable of values
        values = list(hist)

    # Validate sizes
    if len(edges) != len(values) + 1:
        raise ValueError("Number of bin edges must be one more than number of values")

    # Determine expected number of value fields
    n_value_fields = len(field_names) - 1
    points = []

    for i, v in enumerate(values):
        # coordinate
        if coord_offset == 0.0:
            x = edges[i]
        elif coord_offset == 1.0:
            x = edges[i + 1]
        else:
            x = 0.5 * (edges[i] + edges[i + 1])

        y_vals = make_value(v)
        # normalise to tuple/list
        if not isinstance(y_vals, (tuple, list)):
            y_vals = (y_vals,)
        if len(y_vals) != n_value_fields:
            raise ValueError(f"make_value returned {len(y_vals)} values but expected {n_value_fields} for fields {field_names[1:]}")

        point = {name: val for name, val in zip(field_names, [x] + list(y_vals))}
        points.append(point)

    # Resolve scale
    if scale is True:
        if hasattr(hist, "scale"):
            graph_scale = hist.scale
        else:
            graph_scale = None
    else:
        graph_scale = scale

    # Build graph dict
    graph = {"points": points, "field_names": field_names}
    if graph_scale is not None:
        graph["scale"] = graph_scale
    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is ``True``,
      in which case this step is skipped). This means that the candidate's class
      declares that it ``implements`` the interface, or the candidate itself declares
      that it ``provides`` the interface.

    - Making sure the candidate defines all the necessary methods.

    - Making sure the methods have the correct signature (to the
      extent possible).

    - Making sure the candidate defines all the necessary attributes.

    :return bool: Returns a true value if everything that could be
       checked passed.

    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    # Step 1: Verify that the candidate claims to provide the interface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(
                    f"Candidate does not claim to provide interface {iface.__name__}"
                )
        except Exception as exc:  # pragma: no cover
            errors.append(
                f"Error checking provided interface: {exc!s}"
            )

    # Step 2: Gather interface members (methods and attributes)
    # We filter out private names and special attributes
    try:
        interface_attrs = [
            nm
            for nm in iface.__dict__
            if not nm.startswith("_")
            and not callable(iface.__dict__[nm])
        ]
        interface_methods = [
            nm
            for nm, val in iface.__dict__.items()
            if not nm.startswith("_") and callable(val)
        ]
    except Exception:  # pragma: no cover
        # Fallback: use dir() if __dict__ access fails
        interface_attrs = [
            nm
            for nm in dir(iface)
            if not nm.startswith("_")
            and not callable(getattr(iface, nm, None))
        ]
        interface_methods = [
            nm
            for nm in dir(iface)
            if not nm.startswith("_") and callable(getattr(iface, nm, None))
        ]

    # Determine candidate type: class or instance
    candidate_type = candidate if isinstance(candidate, type) else type(candidate)

    import inspect  # Local import as no top-level imports allowed

    # Step 3: Verify methods
    for name in interface_methods:
        if not hasattr(candidate_type, name):
            errors.append(f"Missing method '{name}'")
        else:
            iface_method = getattr(iface, name)
            cand_method = getattr(candidate_type, name)
            try:
                sig_iface = inspect.signature(iface_method)
                sig_cand = inspect.signature(cand_method)
            except Exception:  # pragma: no cover
                # Unable to introspect signatures – skip detailed comparison
                continue
            if sig_iface != sig_cand:
                errors.append(
                    f"Signature mismatch for method '{name}': "
                    f"expected {sig_iface}, got {sig_cand}"
                )

    # Step 4: Verify attributes
    for name in interface_attrs:
        if not hasattr(candidate_type, name):
            errors.append(f"Missing attribute '{name}'")

    # Final: Raise if any errors were collected
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])  # pragma: no cover
        raise Invalid("; ".join(errors))  # pragma: no cover

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's
      class declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    # 1. Check claimed provision of interface (unless tentative)
    if not tentative:
        if not iface.providedBy(candidate):
            raise zope.interface.Invalid(
                f"{candidate!r} does not provide interface {iface!r}"
            )

    # Helper to get interface member type
    InterfaceAttribute = getattr(zope.interface, "Attribute", None)
    if InterfaceAttribute is None:
        # Attempt to locate Attribute class via interfaces module
        try:
            InterfaceAttribute = zope.interface.interfaces.Attribute
        except Exception:
            InterfaceAttribute = None  # pragma: no cover

    # Inspect interface's definition dictionary.
    for name, member in iface.__dict__.items():
        # Skip internal and private members
        if name.startswith("_"):
            continue

        # Determine if member is an attribute or a callable
        if InterfaceAttribute and isinstance(member, InterfaceAttribute):
            # Expected to be a data attribute
            if not hasattr(candidate, name):
                errors.append(f"Missing attribute '{name}' in {candidate!r}")
        else:
            # Expected to be a method (callable or descriptor)
            if not hasattr(candidate, name):
                errors.append(f"Missing method '{name}' in {candidate!r}")
            else:
                cand_obj = getattr(candidate, name)
                # Verify the signature if possible
                try:
                    cand_sig = inspect.signature(cand_obj)
                except Exception:
                    cand_sig = None

                iface_sig = None
                # Try to obtain the interface method signature
                # Interface method may expose a 'signature' attribute
                if hasattr(member, "signature"):
                    try:
                        iface_sig = inspect.signature(member.signature)
                    except Exception:
                        iface_sig = None
                else:
                    # Fallback: attempt to introspect the interface method itself
                    try:
                        iface_sig = inspect.signature(member)
                    except Exception:
                        iface_sig = None

                if cand_sig is not None and iface_sig is not None:
                    # Compare number of parameters ignoring *args/**kwargs differences
                    if len(cand_sig.parameters) != len(iface_sig.parameters):
                        errors.append(
                            f"Signature mismatch in method '{name}' "
                            f"(expected {len(iface_sig.parameters)} "
                            f"parameters, got {len(cand_sig.parameters)})"
                        )

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("; ".join(errors))

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    from zope.interface import Invalid

    # Helper to compare signatures
    def _signatures_match(interface_sig, candidate_sig):
        # If the interface signature is a simple string or does not expose parameters, skip check
        try:
            int_params = list(interface_sig.parameters)
        except AttributeError:
            return True
        cand_params = list(candidate_sig.parameters)
        if len(int_params) != len(cand_params):
            return False
        for ip, cp in zip(int_params, cand_params):
            if ip.name != cp.name or ip.kind != cp.kind:
                return False
        return True

    errors = []

    # 1. Verify providedBy
    if not tentative:
        try:
            provided = iface.providedBy(candidate)
        except Exception:
            provided = False
        if not provided:
            errors.append(Invalid("%r does not provide %r" % (candidate, iface)))

    # 2. Verify methods
    # ``methods`` returns a mapping of name -> interface signature
    try:
        interface_methods = iface.methods()
    except Exception:
        interface_methods = {}
    for name, interface_sig in interface_methods.items():
        if not hasattr(candidate, name):
            errors.append(Invalid("%r missing method %s" % (candidate, name)))
            continue
        func = getattr(candidate, name)
        try:
            candidate_sig = inspect.signature(func)
        except (ValueError, TypeError):
            candidate_sig = None
        if candidate_sig is not None:
            if not _signatures_match(interface_sig, candidate_sig):
                errors.append(
                    Invalid(
                        "%r method %s signature mismatch: expected %s, got %s"
                        % (candidate, name, interface_sig, candidate_sig)
                    )
                )

    # 3. Verify attributes
    try:
        interface_attrs = iface.attributes()
    except Exception:
        interface_attrs = {}
    for name in interface_attrs:
        if not hasattr(candidate, name):
            errors.append(Invalid("%r missing attribute %s" % (candidate, name)))

    if errors:
        if len(errors) == 1:
            raise errors[0]
        else:
            # Aggregate
            message = "\n".join(e.args[0] for e in errors)
            raise Invalid(message)

    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # Resolve the class of the candidate
    cand_cls = candidate if isinstance(candidate, type) else candidate.__class__
    # If the candidate is a subclass of the interface, it trivially satisfies it
    if issubclass(cand_cls, iface):
        return True
    # Gather required abstract methods from the interface, if any
    required = []
    for attr, obj in vars(iface).items():
        if getattr(obj, "__isabstractmethod__", False):
            required.append(attr)
    # Check that the candidate implements each required method
    missing = [name for name in required if not hasattr(cand_cls, name)]
    if missing and not tentative:
        raise TypeError(
            f"{cand_cls.__name__} does not implement required methods: "
            f"{', '.join(missing)}"
        )
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Ensure we are dealing with a class
    if not isinstance(candidate, type):
        candidate = type(candidate)

    # Must be subclass of iface
    if not issubclass(candidate, iface):
        if tentative:
            return False
        raise TypeError(f'{candidate.__name__!r} is not a subclass of {iface.__name__!r}')

    # Check abstract methods (if iface uses ABC)
    abstract_methods = getattr(iface, '__abstractmethods__', set())
    if abstract_methods:
        missing = [name for name in abstract_methods if not hasattr(candidate, name)]
        if missing:
            if tentative:
                return False
            raise TypeError(f'{candidate.__name__!r} lacks abstract methods: {missing}')

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # candidate must be a class (or a type alias)
    if not isinstance(candidate, type):
        raise TypeError("candidate must be a class or type")
    # If tentative, just return True without full checking
    if tentative:
        return True
    # Basic subclass check: candidate should be a subclass of iface
    if not issubclass(candidate, iface):
        raise TypeError(f"{candidate.__name__} does not inherit from {iface.__name__}")
    # Ensure all abstract methods (if any) are implemented
    abstract_methods = getattr(iface, '__abstractmethods__', set())
    for name in abstract_methods:
        if not hasattr(candidate, name):
            raise TypeError(f"{candidate.__name__} is missing required method {name}")
        if getattr(candidate, name) is getattr(iface, name):
            # method was not overridden
            raise TypeError(f"{candidate.__name__} does not override abstract method {name}")
    return True

def determineMetaclass(bases, explicit_mc=None):
        """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

        # If an explicit metaclass is given, it takes precedence.
        if explicit_mc is not None:
            meta_candidate = explicit_mc
        else:
            # Collect metaclasses of the given bases.
            metaclasses = [type(b) for b in bases if isinstance(b, type)]
            if not metaclasses:
                return object

            # Start with the first metaclass and attempt to
            # find a common super‑metaclass that satisfies all bases.
            meta_candidate = metaclasses[0]
            for other_meta in metaclasses[1:]:
                if issubclass(other_meta, meta_candidate):
                    meta_candidate = other_meta
                elif not issubclass(meta_candidate, other_meta):
                    # No common metaclass – fall back to object.
                    meta_candidate = object
                    break

        # Ensure the returned value is a real metaclass object.
        if not isinstance(meta_candidate, type):
            meta_candidate = type(meta_candidate)
        return meta_candidate

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Validate bases: all of them must be types
    for b in bases:
        if not isinstance(b, type):
            raise TypeError(f"Base {b!r} is not a type")

    # If an explicit metaclass is provided, it must be compatible with all base metaclasses
    if explicit_mc is not None:
        for b in bases:
            base_meta = type(b)
            if not issubclass(explicit_mc, base_meta):
                raise TypeError(
                    f"Explicit metaclass {explicit_mc!r} is not a subclass of base's metaclass {base_meta!r}"
                )
        return explicit_mc

    # No explicit metaclass: infer from the bases
    metaclasses = [type(b) for b in bases]
    if not metaclasses:
        # If no bases, default to the built‑in type
        return type

    # Find the most derived metaclass, or raise an error if there is a conflict
    meta = metaclasses[0]
    for m in metaclasses[1:]:
        if issubclass(m, meta):
            meta = m
        elif not issubclass(meta, m):
            raise TypeError(
                f"Metaclass conflict: {m!r} is not a subclass of {meta!r}"
            )
    return meta

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metafactory is given, it wins but must be compatible
    if explicit_mc is not None:
        metaclass = explicit_mc
    else:
        # No explicit metaclass: derive from bases
        if not bases:
            metaclass = type
        else:
            # Collect metaclasses of each base
            base_meta = {type(b) for b in bases}
            # Choose the most derived metaclass
            for mc in base_meta:
                # `mc` is a candidate if it is subclass of all other metaclasses
                if all(issubclass(mc, other) for other in base_meta):
                    metaclass = mc
                    break
            else:
                # If we get here, there was no single most derived metaclass
                # Default to the built-in `type`
                metaclass = type

    # Validate that the chosen metaclass is a class (i.e., a subclass of `type`)
    if not isinstance(metaclass, type):
        raise TypeError(
            f"Metaclass '{metaclass}' is not a class; cannot be used as metaclass"
        )

    # If an explicit metaclass was given, ensure it is subsumed by the base metaclasses
    if explicit_mc is not None:
        base_meta = {type(b) for b in bases}
        # All base metaclasses must be subclasses of the explicit metaclass
        if not all(issubclass(mc, explicit_mc) for mc in base_meta):
            raise TypeError(
                f"Explicit metaclass '{explicit_mc.__name__}' is not compatible "
                "with the base classes' metaclasses"
            )

    return metaclass

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is not __marker:
            return default
        raise KeyError(key)
    for map_obj in (self._pb.IntMap, self._pb.FloatMap,
                    self._pb.StringMap, self._pb.BoolMap):
        if key in map_obj:
            return map_obj.pop(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self._store:
        raise KeyError('dict is empty')
    # Find key with lowest access count
    min_key = min(self._store, key=lambda k: self._freq.get(k, 0))
    value = self._store.pop(min_key)
    # Remove its frequency entry
    self._freq.pop(min_key, None)
    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('dictionary is empty')
    # determine the lowest frequency among the keys
    minfreq = min(self._freq.values())
    # locate a key with that frequency
    for key in self:
        if self._freq.get(key) == minfreq:
            value = self[key]
            del self[key]
            # clean up frequency bookkeeping
            self._freq.pop(key, None)
            if hasattr(self, '_freq_table'):
                self._freq_table[minfreq].pop(key, None)
                if not self._freq_table[minfreq]:
                    del self._freq_table[minfreq]
            return (key, value)
    # Fallback – pop any item if frequency data is inconsistent
    key, value = dict.popitem(self)
    return (key, value)

def popitem(self):
        """Remove and return the `(key, value)` pair least frequently used."""
        if not self._data:
            raise KeyError('dictionary is empty')
        # Find key with the smallest frequency count
        min_key = min(self._data, key=lambda k: self._freq.get(k, 0))
        value = self._data.pop(min_key)
        self._freq.pop(min_key, None)
        return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    node = self._head[2]
    if node is self._tail:
        raise KeyError('list is empty')
    self._remove(node)
    return (node[0], node[1])

