def find_tags(text: str, replacer: callable = None) -> Tuple[Set[str], str]:
    import re
    from typing import Set, Tuple

    tags: Set[str] = set()
    inside_code = False
    output_lines = []

    code_pat = re.compile(r'^```')
    tag_pat = re.compile(r'\b([A-Z][A-Z0-9_]*)\b')

    for line in text.splitlines():
        if code_pat.match(line.rstrip()):
            inside_code = not inside_code
            output_lines.append(line)
            continue

        if inside_code:
            output_lines.append(line)
        else:
            if replacer is None:
                for m in tag_pat.finditer(line):
                    tags.add(m.group(1))
                output_lines.append(line)
            else:
                def repl_func(m):
                    tag = m.group(1)
                    tags.add(tag)
                    return replacer(tag)
                new_line = tag_pat.sub(repl_func, line)
                output_lines.append(new_line)

    return tags, '\n'.join(output_lines)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    _URL_RE = re.compile(r'\b(?P<url>https?://[^\s<]+)')
    def _linkify(m):
        url = m.group('url')
        attrs = ' target="_blank" rel="noopener noreferrer"'
        return f'<a href="{url}"{attrs}>{url}</a>'
    return _URL_RE.sub(_linkify, text)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    url_re = re.compile(r'\b(?:https?://|www\.)[^\s<]+')
    def replace(match):
        url = match.group(0)
        href = url
        if href.startswith('www.'):
            href = 'http://' + href
        return f'<a href="{href}" target="_blank" rel="noopener noreferrer">{url}</a>'
    return url_re.sub(replace, text)

