    return url_re.sub(repl, text)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    result = []
    i = 0
    length = len(text)
    while i < length:
        # Detect the start of a URL.
        if text.startswith('http://', i) or text.startswith('https://', i):
            # Find the end of the URL.
            j = i
            while j < length and text[j] not in ' \t\r\n<>':
                j += 1
            url = text[i:j]
            link = f'<a href="{url}" target="_blank" rel="noopener">{url}</a>'
            result.append(link)
            i = j
        else:
            result.append(text[i])
            i += 1
    return ''.join(result)

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    scheme, netloc, _, _, _ = urlsplit(url)
    if scheme not in ("http", "https", "ftp", "ftps"):
        return None

    req = Request(url, method="HEAD")
    req.add_header("Host", netloc)

    try:
        resp = urlopen(req)
        try:
            if hasattr(resp, "status") and resp.status != 200 and scheme not in ("ftp", "ftps"):
                return None
            content_type = resp.getheader("Content-Type")
            return content_type
        finally:
            resp.close()
    except Exception:
        return None

