def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        import xmlsec
        from lxml import etree
    except Exception:
        # XML Digital Signature library or parser not available
        return False

    try:
        # Parse the XML document
        doc_root = etree.fromstring(doc.encode('utf-8'))

        # Try to find the Signature element either inside the doc or
        # provided separately
        if signature:
            sig_node = etree.fromstring(signature.encode('utf-8'))
        else:
            ns = {'ds': 'http://www.w3.org/2000/09/xmldsig#'}
            sig_node = doc_root.find('.//ds:Signature', namespaces=ns)

        if sig_node is None:
            return False

        # Load the public key
        key = xmlsec.Key.from_memory(
            public_key.encode('utf-8'),
            xmlsec.KeyDataFormat.PEM,
            None
        )

        # Verify the signature
        ctx = xmlsec.SignatureContext()
        ctx.key = key
        return ctx.verify(sig_node)

    except Exception:
        return False

def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.

    :param public_key: The public key material (PEM string or file path) used to verify the signature.
    :param doc: The XML document as a string or lxml element.
    :param signature: The explicit signature element as a string, lxml element, or None to find it within the document.
    :return: True if the signature is valid, False otherwise.
    """
    from lxml import etree
    import xmlsec

    # Ensure we have a root element to work with
    if isinstance(doc, str):
        try:
            root = etree.fromstring(doc)
        except Exception as e:
            # document could be a full XML string with declaration, use parser
            parser = etree.XMLParser(remove_blank_text=True, recover=True)
            root = etree.fromstring(doc.encode('utf-8'), parser)
    else:
        root = doc

    # Locate the signature element
    if signature is None:
        sig_node = xmlsec.tree.find_node(root, xmlsec.Node.SIGNATURE)
        if sig_node is None:
            return False
    else:
        if isinstance(signature, str):
            try:
                sig_node = etree.fromstring(signature)
            except Exception:
                # if signature contains xmlns it's fine
                sig_node = etree.XML(signature)
        else:
            sig_node = signature

    # Prepare the signing context
    ctx = xmlsec.SignatureContext()

    # Load the public key; support both PEM string and file path
    if isinstance(public_key, (bytes, str)):
        try:
            # Try as a file path first
            key = xmlsec.Key.from_file(public_key, xmlsec.KeyFormat.PEM, None)
        except (OSError, xmlsec.KeyError):
            # Fallback to key from memory
            key = xmlsec.Key.from_memory(public_key, xmlsec.KeyFormat.PEM, None)
    else:
        raise TypeError("public_key must be a bytes or str containing PEM data or path to a PEM file")

    ctx.key = key

    # Verify the signature
    try:
        ctx.verify(sig_node)
        return True
    except (xmlsec.VerificationError, xmlsec.Error):
        return False

