            result["properties"] = data["properties"]
        # Links
        for link in data.get("links", []):
            rel = link.get("rel")
            href = link.get("href")
            if not rel or not href:
                continue
            # Some rels are space separated
            for r in rel.split():
                if r == "hcard" or r in ("http://microformats.org/profile/hcard",
                                         "http://openid.net/specs/connect/1.0/authorization_endpoint"):
                    result["hcard_url"] = href
                # Store general mapping, allow list of values
                if r in result:
                    if isinstance(result[r], list):
                        result[r].append(href)
                    else:
                        result[r] = [result[r], href]
                else:
                    result[r] = href
        return result
    except Exception:
        # Not JSON, try XRD
        try:
            # Register a dummy namespace map to handle default namespace
            namespace = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
            root = ET.fromstring(document)
            # Subject
            sub = root.find("xrd:Subject", namespace)
            if sub is not None:
                result["subject"] = sub.text
            # Links
            for link in root.findall("xrd:Link", namespace):
                rel = link.get("rel")
                href = link.get("href")
                if not rel or not href:
                    continue
                for r in rel.split():
                    if r == "hcard" or r == "http://microformats.org/profile/hcard":
                        result["hcard_url"] = href
                    if r in result:
                        if isinstance(result[r], list):
                            result[r].append(href)
                        else:
                            result[r] = [result[r], href]
                    else:
                        result[r] = href
            return result
        except Exception:
            # Failed to parse
            return {}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
    except Exception:
        def _parse_xrd(doc: str) -> Dict:
            result: Dict = {}
            root = ET.fromstring(doc)
            subj = root.find('.//{*}Subject')
            if subj is not None:
                result['subject'] = subj.text
            for link in root.findall('.//{*}Link'):
                href = link.attrib.get('href')
                rel = link.attrib.get('rel', '').lower()
                if href:
                    if 'hcard' in rel:
                        result['hcard_url'] = href
                    if 'login' in rel:
                        result['login_url'] = href
            for prop in root.findall('.//{*}Property'):
                rel = prop.attrib.get('rel', '').lower()
                if 'public_key' in rel and prop.text:
                    result['public_key'] = prop.text
            return result
        return _parse_xrd(document)
    def _parse_json(data: Dict) -> Dict:
        result: Dict = {}
        if 'subject' in data:
            result['subject'] = data['subject']
        properties = data.get('properties', {})
        for key, value in properties.items():
            key_lower = key.lower()
            if 'public_key' in key_lower:
                result['public_key'] = value
            if key_lower.endswith('login_url'):
                result['login_url'] = value
        for link in data.get('links', []):
            href = link.get('href')
            rel = link.get('rel', '').lower()
            if href:
                if 'hcard' in rel:
                    result['hcard_url'] = href
                if 'login' in rel:
                    result['login_url'] = href
        return result
    return _parse_json(data)

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # First try JSON (the newer format)
    try:
        data = json.loads(document)
        result = {}
        result["subject"] = data.get("subject")
        result["aliases"] = data.get("aliases", [])
        for link in data.get("links", []):
            rel = link.get("rel", "")
            href = link.get("href")
            if rel.endswith("hcard"):
                result["hcard_url"] = href
            elif rel.endswith("node"):
                result["node_url"] = href
            elif rel.endswith("sharedkey"):
                result["sharedkey"] = href
        return result
    except Exception:
        # Assume the XRD (old) format
        try:
            root = ET.fromstring(document)
        except Exception:
            return {}

        result = {}
        # Extract the subject
        subject = None
        for elem in root.iter():
            if elem.tag.endswith("Subject"):
                subject = elem.text
                break
        result["subject"] = subject

        # Extract aliases
        aliases = []
        for elem in root.iter():
            if elem.tag.endswith("Alias"):
                aliases.append(elem.text)
        result["aliases"] = aliases

        # Extract links
        for elem in root.iter():
            if elem.tag.endswith("Link"):
                rel = elem.attrib.get("rel", "")
                href = elem.attrib.get("href")
                if rel.endswith("hcard"):
                    result["hcard_url"] = href
                elif rel.endswith("node"):
                    result["node_url"] = href
                elif rel.endswith("sharedkey"):
                    result["sharedkey"] = href

        return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return {}
    doc = document.strip()
    # Try JSON first
    if doc.startswith('{'):
        try:
            import json
            return json.loads(doc)
        except Exception:
            # fall back to XRD parsing
            pass
    # Assume XRD XML
    try:
        from xml.etree import ElementTree as ET
    except Exception:
        return {}
    try:
        ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
        root = ET.fromstring(doc)
        result = {}
        subject = root.find('xrd:subject', ns)
        if subject is not None and subject.text:
            result['subject'] = subject.text
        # Extract links
        links = []
        for link in root.findall('xrd:Link', ns):
            link_dict = {}
            rel = link.attrib.get('rel')
            if rel:
                link_dict['rel'] = rel
            type_attr = link.attrib.get('type')
            if type_attr:
                link_dict['type'] = type_attr
            href = link.attrib.get('href')
            if href:
                link_dict['href'] = href
            template = link.attrib.get('template')
            if template:
                link_dict['template'] = template
            if link_dict:
                links.append(link_dict)
        if links:
            result['links'] = links
        return result
    except Exception:
        return {}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # First try the JSON format
    try:
        data = json.loads(document)
        # The JSON WebFinger format includes 'links' list
        links = []
        for link in data.get('links', []):
            rel = link.get('rel')
            href = link.get('href')
            if rel and href:
                links.append({'rel': rel, 'href': href})
        return {'subject': data.get('subject'), 'links': links}
    except Exception:
        # Fallback to XRD format
        try:
            root = ET.fromstring(document)
            # In XRD, Subject is a direct child
            subject_el = root.find('Subject')
            subject = subject_el.text if subject_el is not None else None
            links = []
            for link in root.findall('Link'):
                rel = link.attrib.get('rel')
                href = link.attrib.get('href')
                if rel and href:
                    links.append({'rel': rel, 'href': href})
            return {'subject': subject, 'links': links}
        except Exception:
            return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split('@')[1]
    except Exception:
        return None
    url = "http://%s/.well-known/webfinger?resource=acct:%s" % (host, handle)
    try:
        with closing(urllib2.urlopen(url)) as page:
            return page.read()
    except (urllib2.URLError, ValueError):
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split("@")[1]
    except Exception:
