    url = f"https://{host}/.well-known/webfinger?resource=acct:{quote(handle)}"
    try:
        with closing(urllib2.urlopen(url)) as page:
            data = page.read()
            if isinstance(data, bytes):
                data = data.decode("utf-8", errors="ignore")
            return data
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        if handle.startswith('acct:'):
            resource = handle[5:]
        else:
            resource = handle
        host = resource.split('@')[1]
    except Exception:
        return None
    url = "https://{host}/.well-known/webfinger?resource=acct:{resource}".format(
        host=host, resource=quote(resource)
    )
    try:
        resp = urllib2.urlopen(url)
        data = resp.read()
        resp.close()
        return data
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        host = handle.split("@")[1]
    except (IndexError, AttributeError):
        return None
    url = 'https://%s/.well-known/webfinger?resource=%s' % (host, urllib2.quote(handle))
    try:
        with closing(urllib2.urlopen(url)) as page:
            return page.read().decode('utf-8', errors='replace')
    except Exception:
        return None

