def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    logger.debug("send_document: url=%s, data=%s, timeout=%s, method=%s", url, data, timeout, method)
    headers = CaseInsensitiveDict({'User-Agent': USER_AGENT})
    if 'headers' in kwargs:
        headers.update(kwargs['headers'])
    kwargs.update({'data': data, 'timeout': timeout, 'headers': headers})
    method_name = method.lower()
    try:
        if method_name == 'post':
            response = requests.post(url, *args, **kwargs)
        elif method_name == 'get':
            response = requests.get(url, *args, **kwargs)
        elif method_name == 'put':
            response = requests.put(url, *args, **kwargs)
        elif method_name == 'delete':
            response = requests.delete(url, *args, **kwargs)
        elif method_name == 'head':
            response = requests.head(url, *args, **kwargs)
        elif method_name == 'options':
            response = requests.options(url, *args, **kwargs)
        else:
            raise ValueError(f"Unsupported HTTP method: {method}")
        logger.debug("send_document: response status code %s", response.status_code)
        return response.status_code, None
    except RequestException as ex:
        logger.debug("send_document: exception %s", ex)
        return None, ex

def list_of_file_names(settings_dirs, spec_option):
    """Return a sorted list of fully qualified file names from the provided directories.

    Parameters
    ----------
    settings_dirs : list or tuple of str
        Directories to search for files.
    spec_option : str or None
        Optional string to filter file names; only files whose names start with this
        string will be included. If None, all files are included.

    Returns
    -------
    list of str
        Sorted list of absolute paths to files that match the filter.
    """
    import os
    files = []
    for directory in settings_dirs:
        try:
            if not os.path.isdir(directory):
                continue
            for fname in os.listdir(directory):
                if spec_option and not fname.startswith(spec_option):
                    continue
                full_path = os.path.join(directory, fname)
                if os.path.isfile(full_path):
                    files.append(full_path)
        except OSError:
            # Skip directories that cannot be accessed
            continue
    return sorted(files)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    file_names = []
    for directory in settings_dirs:
        try:
            for root, dirs, files in os.walk(directory):
                for fname in files:
                    if spec_option is None or fname.endswith(spec_option):
                        file_names.append(os.path.join(root, fname))
        except OSError:
            continue
    return sorted(file_names)

