                data = yaml.safe_load(f)
        except FileNotFoundError as e:
            raise IRValidatorException(f"File not found: {yaml_file}") from e
        except Exception as e:
            raise IRValidatorException(f"Error reading or parsing YAML file: {e}") from e

        if data is None or not isinstance(data, dict):
            raise IRValidatorException(f"YAML file '{yaml_file}' did not contain a valid dictionary")

        # Verify that all mandatory fields are present
        required = getattr(cls, 'REQUIRED_FIELDS', None)
        if required is None:
            # If the class does not define REQUIRED_FIELDS, nothing to validate
            return data

        missing = [field for field in required if field not in data]
        if missing:
            missing_str = ", ".join(missing)
            raise IRValidatorException(f"Mandatory field(s) missing in '{yaml_file}': {missing_str}")

        return data

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise IRValidatorException("yaml_file argument must be supplied")

    try:
        with yaml_file.open('r') as f:
            data = yaml.safe_load(f)
    except yaml.YAMLError as exc:
        raise IRValidatorException(f"Error parsing YAML file: {exc}") from exc
    except FileNotFoundError as exc:
        raise IRValidatorException(f"File {yaml_file} not found") from exc

    if not isinstance(data, dict):
        raise IRValidatorException(f"YAML root must be a mapping but got {type(data).__name__}")

    required_fields = getattr(cls, 'REQUIRED_FIELDS', [])
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing mandatory fields: {', '.join(missing)}")

    return data

def validate_from_file(cls, yaml_file=None):
    """
    Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise IRValidatorException("yaml_file argument must be supplied")

    try:
        with open(yaml_file, "r") as f:
            data = yaml.safe_load(f)
    except yaml.YAMLError as ye:
        raise IRValidatorException(f"Error parsing YAML file: {ye}") from ye

    if data is None:
        raise IRValidatorException("YAML file is empty or could not be parsed")

    try:
        jsonschema.validate(instance=data, schema=cls.schema)
    except jsonschema.ValidationError as ve:
        raise IRValidatorException(f"Validation error: {ve.message}") from ve

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Iterate over a list copy of items so that we can modify the dict safely
    for parser_name, options in list(parser_dict.items()):
        include = options.pop('include', None)
        if not include:
            continue
        # If `include` is a mapping, insert the sub-parsers under the given keys
        if isinstance(include, dict):
            for local_key, inc_name in include.items():
                if inc_name not in parser_dict:
                    raise KeyError(f'Included parser {inc_name!r} not found')
                # Store a copy of the included spec so later changes do not affect the original
                options[local_key] = parser_dict[inc_name].copy()
        else:
            # Assume a sequence of parser names; merge into the current options
            for inc_name in include:
                if inc_name not in parser_dict:
                    raise KeyError(f'Included parser {inc_name!r} not found')
                options.update(parser_dict[inc_name])

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    includes = parser_dict.pop('include', None)
    if not includes:
        return parser_dict
    if isinstance(includes, dict):
        includes = [includes]
    for inc in includes:
        if isinstance(inc, dict):
            for key, val in inc.items():
                if key in parser_dict and isinstance(parser_dict[key], dict) and isinstance(val, dict):
                    parser_dict[key].update(val)
                else:
                    parser_dict[key] = val
    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        return
    includes = parser_dict.pop('include', None)
    if includes is None:
        return
    # Merge included dictionaries into the current parser dict
    if isinstance(includes, dict):
        for k, v in includes.items():
            if isinstance(v, dict):
                existing = parser_dict.get(k, {})
                if isinstance(existing, dict):
                    existing.update(v)
                    parser_dict[k] = existing
                else:
                    parser_dict[k] = v
            else:
                parser_dict[k] = v
    elif isinstance(includes, list):
        for item in includes:
            if isinstance(item, dict):
                parser_dict.update(item)
    # Recursively resolve includes in nested dictionaries
    for v in parser_dict.values():
        if isinstance(v, dict):
            self._include_groups(v)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    for arg in getattr(self, "args", []):
        if not isinstance(arg, _BaseOpt):
            continue
        # Prefer an explicit value from the spec, if present
        if getattr(self, "spec", None) and arg.name in self.spec:
            defaults[arg.name] = self.spec[arg.name]
            continue
        # Fallback to the option's own default, if it has one
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default
            continue
        # Handle nested dictionary options, merging defaults recursively
        if isinstance(arg, DictOption) and getattr(arg, "scheme", None):
            nested = arg.scheme.get_spec_defaults()
            if nested:
                defaults[arg.name] = nested
    return defaults

def get_spec_defaults(self):
