    if hasattr(self, "spec") and self.spec is not None:
        try:
            spec_vals = self.spec
            if isinstance(spec_vals, dict):
                defaults.update(spec_vals)
            else:
                # Try to convert spec to a dictionary if possible
                defaults.update(dict(spec_vals))
        except Exception:
            # Fail silently; spec may not be directly usable as a dict
            pass
    # Merge defaults from the scheme, respecting explicit spec values
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            continue
        # Skip if spec already provided a value for this argument
        if arg.name in defaults:
            continue
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default
        # Recursively handle nested dictionary options
        if isinstance(arg, DictOption) and arg.scheme:
            sub = arg.scheme.get_spec_defaults()
            if sub:
                defaults[arg.name] = sub
    return defaults

def get_spec_defaults(self):
