def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        deprecated_map = getattr(self, "deprecated_arg_mapping", {})
        if not deprecated_map:
            return

        # Helper to warn about a specific deprecated key
        def _warn_deprecated(source_name, old_key, new_key):
            warnings.warn(
                f"Argument '{old_key}' from {source_name} is deprecated in favour of "
                f"'{new_key}'. It will be removed in a future version.",
                category=DeprecationWarning,
                stacklevel=3,
            )

        # Check CLI arguments for deprecated keys
        for old_key, new_key in deprecated_map.items():
            if old_key in cli_args:
                _warn_deprecated("CLI", old_key, new_key)

        # Check answer file arguments for deprecated keys
        for old_key, new_key in deprecated_map.items():
            if old_key in answer_file_args:
                _warn_deprecated("Answer file", old_key, new_key)

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Retrieve the parser instance for the given command
    parser = getattr(self, "_parsers", {}).get(command_name)
    if parser is None:
        raise KeyError(f"Unknown command '{command_name}'.")
    # Prefer an explicit method if available; fall back to common attributes
    if hasattr(parser, "get_options"):
        return list(parser.get_options())
    if hasattr(parser, "options"):
        return list(parser.options)
    raise AttributeError("Parser does not expose options via 'options' attribute or 'get_options' method.")

