def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        # Skip if no conditional requirement defined
        if 'required_when' not in opt:
            continue
        cond = opt['required_when']
        matched = False
        # Try to evaluate the condition
        try:
            if callable(cond):
                # Try with both args and command_name first
                try:
                    matched = bool(cond(args, command_name))
                except TypeError:
                    # Fallback to single argument
                    matched = bool(cond(args))
            else:
                # Non-callable conditions: treat truthy values as True
                matched = bool(cond)
        except Exception:
            # If evaluation fails, treat as not matched
            matched = False
        if matched:
            # Prefer explicit name if provided, else dest
            name = opt.get('name') or opt.get('dest')
            if name:
                required.append(name)
    return required

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        conditionally_required = []

        # options_spec may be a dict or list of spec dictionaries
        if isinstance(options_spec, dict):
            specs = options_spec.items()
        else:
            # Assume list of spec dictionaries
            specs = ((opt.get('name') or opt.get('arg'), opt) for opt in options_spec)

        for opt_name, spec in specs:
            if not opt_name:
                continue
            req_when = spec.get('required_when')
            if not req_when:
                continue

            matched = False
            # If the condition is a callable, call it with args
            if callable(req_when):
                try:
                    matched = bool(req_when(args))
                except Exception:
                    matched = False
            # If the condition is a mapping of argument names to values
            elif isinstance(req_when, dict):
                matched = True
                for cond_key, cond_val in req_when.items():
                    if cond_key not in args:
                        matched = False
                        break
                    arg_value = args[cond_key]
                    if isinstance(cond_val, (list, tuple, set)):
                        if arg_value not in cond_val:
                            matched = False
                            break
                    else:
                        if arg_value != cond_val:
                            matched = False
                            break
            # Fallback: no match
            if matched:
                conditionally_required.append(opt_name)

        return conditionally_required

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        if isinstance(opt, dict):
            name = opt.get('name')
            cond = opt.get('required_when')
        else:
            name = getattr(opt, 'name', None)
            cond = getattr(opt, 'required_when', None)
        if not name or not cond:
            continue

        matched = False
        if callable(cond):
            try:
                matched = bool(cond(command_name, options_spec, args))
            except Exception:
                matched = False
        elif isinstance(cond, (list, tuple)):
            matched = any(args.get(c) for c in cond)
        else:
            matched = bool(cond)

        if matched:
            required.append(name)
    return required

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
    """List arguments with ``required_when`` condition matched.

