def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve argument specifications from parsed yaml
    args_def = self.parsed_yaml.get('args', {})
    for arg_name, arg_attrs in args_def.items():
        # Handle list format used for positional arguments
        if isinstance(arg_attrs, list):
            # The attribute dict should be the first (and only) element
            for item in arg_attrs:
                if isinstance(item, dict):
                    arg_attrs = item
                break
        # Only proceed if a maximum length is defined
        max_len = arg_attrs.get('len')
        if max_len is None:
            continue
        if arg_name not in args:
            continue
        value = args[arg_name]
        try:
            value_len = len(value)
        except Exception:
            # Not a sized object – skip length check
            continue
        if value_len > max_len:
            abort(
                f"Argument '{arg_name}' exceeds maximum length of {max_len} "
                f"(got length {value_len})"
            )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Prepare a mapping from argument names to their maximum allowed lengths.
    max_lengths = getattr(self, 'max_lengths', {})

    # If explicit max_lengths mapping is not present, try to build it from
    # the parsed YAML specification (if available).
    if not max_lengths and hasattr(self, 'parsed_yaml'):
        spec_args = self.parsed_yaml.get('args', {})
        for arg_name, arg_attrs in spec_args.items():
            if isinstance(arg_attrs, dict):
                # Common names for the length constraint in YAML
                for key in ('max_length', 'length', 'maxLen', 'len'):
                    if key in arg_attrs:
                        max_lengths[arg_name] = arg_attrs[key]
                        break

    # Validate each argument against the determined length constraints.
    for arg_name, value in args.items():
        if arg_name in max_lengths:
            max_len = max_lengths[arg_name]
            # Skip values that cannot be measured for length.
            try:
                val_len = len(value)
            except TypeError:
                continue
            if val_len > max_len:
                raise ValueError(
                    f"Argument '{arg_name}' length {val_len} exceeds "
                    f"maximum allowed {max_len}"
                )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    arg_defs = self.parsed_yaml.get('args', {})
    for arg_name, arg_value in args.items():
        if arg_value is None:
            continue
        arg_spec = arg_defs.get(arg_name, {})
        max_len = arg_spec.get('max_length')
        if max_len is None:
            continue
        try:
            value_len = len(arg_value)
        except Exception:
            continue
        if value_len > max_len:
            raise ValueError(f"Argument '{arg_name}' length {value_len} exceeds maximum allowed {max_len}")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Helper to iterate over args whether dict or list of single‑item dicts
    if isinstance(args, dict):
        iterable = args.items()
    elif isinstance(args, list):
        iterable = (
            (list(a.items())[0][0], list(a.items())[0][1]) for a in args
        )
    else:
        return

    for argname, argattrs in iterable:
        # Interpret argattrs: expect a dict with 'value' and 'length'
        if isinstance(argattrs, dict):
            value = argattrs.get("value")
            max_len = argattrs.get("length")
        else:
            # If argattrs is not a dict, we cannot perform length checking
            continue

        # Skip if either value or length is missing
        if value is None or max_len is None:
            continue

        # Attempt to check the length; ignore non‑len‑supporting values
        try:
            if len(value) > max_len:
                raise ValueError(
                    f"Value of argument '{argname}' (length {len(value)}) exceeds the allowed maximum of {max_len}."
                )
        except TypeError:
            # value does not support len(), can't validate length
            continue

def validate_length_args(self, args):
