    :param args: The received arguments.
    """
    # Allow args to be either a mapping or an iterable of (name, value) pairs
    if isinstance(args, dict):
        items = args.items()
    else:
        items = args

    # Retrieve the mapping of allowed maximum lengths, if defined
    max_lengths = getattr(self, 'max_length_map', {})

    for argname, value in items:
        # Skip if there is no length constraint for this argument
        if argname not in max_lengths:
            continue

        # Skip values that do not support len()
        try:
            val_len = len(value)
        except Exception:
            continue

        max_len = max_lengths[argname]
        if val_len > max_len:
            raise ValueError(
                f"Argument '{argname}' exceeds maximum length of {max_len} (got {val_len})"
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict")

    arg_defs = self.parsed_yaml.get('args', {})
    for arg_name, arg_value in args.items():
        # Find the definition of the argument
        arg_def = None
        if isinstance(arg_defs, dict):
            arg_def = arg_defs.get(arg_name)
        else:  # list of dicts
            for item in arg_defs:
                if isinstance(item, dict) and arg_name in item:
                    arg_def = item[arg_name]
                    break

        if not arg_def or not isinstance(arg_def, dict):
            continue  # No definition, cannot validate choices

        choices = arg_def.get('choices')
        if choices and arg_value not in choices:
            msg = ("Argument `{}` has value `{}` which is not a valid "
                   "choice. Valid choices are: {}").format(arg_name, arg_value, choices)
            raise ConfigurationError(msg)

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the mapping of available choice sets for each argument.
    # The attribute name may vary, use a common fallback.
    available_choices = getattr(self, "choices", {})
    for arg_name, arg_value in args.items():
        # Fetch the set or list of valid values for this argument.
        choices = available_choices.get(arg_name)
        if not choices:
            # If no choices defined for this argument, nothing to validate.
            continue

        # If the argument value is iterable (but not a string), validate each entry.
        if isinstance(arg_value, (list, tuple)):
            for val in arg_value:
                if val not in choices:
                    raise ValueError(
                        f"Invalid value '{val}' for argument '{arg_name}'. "
                        f"Allowed choices: {choices}"
                    )
        else:
            if arg_value not in choices:
                raise ValueError(
                    f"Invalid value '{arg_value}' for argument '{arg_name}'. "
                    f"Allowed choices: {choices}"
                )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg_name, argattrs in args.items():
        if not isinstance(argattrs, dict):
            continue
        arg_type = argattrs.get('type')
        if arg_type != 'choice':
            continue
        value = argattrs.get('value')
        # The allowed values may be stored under 'choices' or 'enum'.
        valid_choices = argattrs.get('choices', argattrs.get('enum', []))
        if not isinstance(valid_choices, (list, tuple, set)):
            continue
        if value not in valid_choices:
            abort(
                f"Invalid value for choice argument '{arg_name}': {value!r}. "
                f"Valid choices are: {valid_choices!r}"
            )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure the input is iterable
    try:
        iterator = iter(args)
    except TypeError:
        raise TypeError("args must be an iterable of tuples (value, min, max)")

    for idx, item in enumerate(iterator, start=1):
        if not isinstance(item, (list, tuple)):
            raise TypeError(f"argument {idx} is not a tuple or list")

        # Each argument must contain a value, a minimum and a maximum
        if len(item) != 3:
            raise ValueError(f"argument {idx} must contain exactly three elements: (value, min, max)")

        value, min_val, max_val = item

        if min_val is None or max_val is None:
            raise ValueError(f"argument {idx} contains None for min or max")

        if min_val > max_val:
            raise ValueError(f"argument {idx} has min > max ({min_val} > {max_val})")

        if not (min_val <= value <= max_val):
            raise ValueError(
                f"value {value} of argument {idx} is not between {min_val} and {max_val}"
            )

    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for idx, arg in enumerate(args):
        # Extract value, min, and max from dict or object
        if isinstance(arg, dict):
            value = arg.get('value')
            min_val = arg.get('min')
            max_val = arg.get('max')
        else:
            value = getattr(arg, 'value', None)
            min_val = getattr(arg, 'min', None)
            max_val = getattr(arg, 'max', None)

        if value is None or min_val is None or max_val is None:
            raise ValueError(f"Argument at index {idx} must have 'value', 'min', and 'max' attributes")

        if not (min_val <= value <= max_val):
            raise ValueError(f"Argument value {value} at index {idx} is not between {min_val} and {max_val}")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    :raises ValueError: If any argument is outside its defined bounds.
    """
    # Allow either a mapping of name -> (value, min, max) or an iterable of such tuples
    if isinstance(args, dict):
        items = args.items()
    else:
        items = enumerate(args)

    for key, val in items:
        # Accept value representations in two common forms:
        #   - A mapping with keys 'value', 'min', 'max'
        #   - A tuple/list of (value, min, max)
        if isinstance(val, dict):
            try:
                value = val["value"]
                min_val = val.get("min")
                max_val = val.get("max")
            except KeyError as exc:
                raise TypeError(f"Dictionary for {key!r} must contain a 'value' key") from exc
        else:
            try:
                value, min_val, max_val = val
            except Exception as exc:  # pragma: no cover
                raise TypeError(f"Argument for {key!r} must be a dict or a 3-tuple of "
                                "(value, min, max)") from exc

        if min_val is not None and value < min_val:
            raise ValueError(f"Argument {key!r} value {value!r} is below minimum {min_val!r}")
        if max_val is not None and value > max_val:
            raise ValueError(f"Argument {key!r} value {value!r} is above maximum {max_val!r}")

    return args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Determine control keys; can be defined on the instance or
    # inferred by a naming convention if not provided.
    control_keys = getattr(self, "control_keys", set())

    # Fallback: treat any key starting with '_' as a control key
    if not control_keys:
        control_keys = {k for k in args if k.startswith("_")}

    for k, v in args.items():
        if k in control_keys:
            control_args[k] = v
        else:
            nested_args[k] = v

    return control_args, nested_args

