def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    command = ["ansible-playbook"]
    if verbose is not None:
        command.append("-" + "v" * verbose)
    else:
        command.append("-vvvvv" if logger.isEnabledFor(logging.DEBUG) else "-v")
    if ansible_args:
        for k, v in ansible_args.items():
            if isinstance(v, bool) and v:
                command.append(f"--{k}")
            else:
                command.append(f"--{k}={v}")
    if extra_vars:
        command.append("--extra-vars")
        command.append(json.dumps(extra_vars))
    command.append(os.path.join(ir_workspace.path, playbook_path))
    logger.debug("Executing Ansible call `%s`", " ".join(command))
    p = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    stdout, stderr = p.communicate()
    if p.returncode != 0:
        raise RuntimeError(f"Ansible reported an error: {stderr.decode('utf-8', errors='replace')}")
    return stdout.decode('utf-8', errors='replace')

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Get the expected type mapping for this parser, if any
    arg_types = getattr(self, f"{parser_name}_arg_types", {})
    for key, value in list(values_dict.items()):
        if key not in arg_types:
            # No type information available; leave as is
            continue

        typ = arg_types[key]
        # Handle boolean specially
        if typ is bool:
            if isinstance(value, str):
                values_dict[key] = value.lower() in ("true", "1", "yes", "on")
            else:
                values_dict[key] = bool(value)
        # Numeric conversion
        elif typ in (int, float) and isinstance(value, str):
            try:
                values_dict[key] = typ(value)
            except ValueError:
                # keep original if conversion fails
                pass
        # Convert comma‑separated string to list
        elif typ is list and isinstance(value, str):
            items = [item.strip() for item in value.split(",") if item.strip()]
            values_dict[key] = items
        # Other types are left untouched or can be added as needed
    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        # Retrieve the option definitions for the requested parser
        parser_cfg = getattr(self, "parsers", {}).get(parser_name, {})
        for opt_name, opt_def in parser_cfg.items():
            if opt_name in values_dict:
                # Prefer an explicit convert method on the option definition
                convert_fn = getattr(opt_def, "convert", None)
                if convert_fn is not None:
                    try:
                        values_dict[opt_name] = convert_fn(values_dict[opt_name])
                    except Exception:
                        # leave the original string value if conversion fails
                        pass
                else:
                    # Fallback: attempt to cast using the declared type
                    opt_type = getattr(opt_def, "type", None)
                    if opt_type is not None:
                        try:
                            values_dict[opt_name] = opt_type(values_dict[opt_name])
                        except Exception:
                            pass
        # The method mutates values_dict in place; no return value is needed.

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten_dict(d, parent_key='', sep='.', result=None):
        if result is None:
            result = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                _flatten_dict(v, new_key, sep=sep, result=result)
            else:
                result[new_key] = v
        return result

    spec_file = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.exists(spec_file):
        raise FileNotFoundError(f"Spec file not found: {spec_file}")

    with open(spec_file, 'r', encoding='utf-8') as f:
        spec = json.load(f)

    return _flatten_dict(spec)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(obj, parent_key='', sep='.'):
        items = {}
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_key = f"{parent_key}{sep}{k}" if parent_key else k
                items.update(_flatten(v, new_key, sep=sep))
        elif isinstance(obj, list):
            for index, item in enumerate(obj):
                new_key = f"{parent_key}{sep}{index}" if parent_key else str(index)
                items.update(_flatten(item, new_key, sep=sep))
        else:
            items[parent_key] = obj
        return items

    # Look for a plugin spec file (default to plugin.json)
    spec_path = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.exists(spec_path):
        # try plugin.yaml
