        raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")
    stripped = path[len(root):]
    if stripped and stripped[0] in (os.sep, '\\'):
        stripped = stripped.lstrip(os.sep + '\\')
    if not stripped:
        raise ValueError(f"Resulting path after removing root is empty")
    return stripped
